    #[test]
    fn positioned_percentage_sizes_use_their_css_containing_blocks() {
        let style = Style {
            position: WPos::Absolute,
            left: WDim::Px(0.0),
            top: WDim::Px(0.0),
            width: WDim::Percent(100.0),
            height: WDim::Percent(100.0),
            ..Style::default()
        };
        let containing_block = LayoutRect {
            x: 10.0,
            y: 20.0,
            width: 100.0,
            height: 80.0,
        };
        let absolute = compute_absolute_rect(
            &style,
            containing_block,
            LayoutRect {
                x: 0.0,
                y: 0.0,
                width: 0.0,
                height: 0.0,
            },
            800.0,
            600.0,
            style.direction,
            false,
        );
        assert_eq!(absolute, containing_block);

        let fixed = compute_fixed_rect(
            &style,
            800.0,
            600.0,
            LayoutRect {
                x: 0.0,
                y: 0.0,
                width: 0.0,
                height: 0.0,
            },
            false,
        );
        assert_eq!((fixed.width, fixed.height), (800.0, 600.0));

        let content_box_with_border = Style {
            width: WDim::Percent(50.0),
            height: WDim::Percent(50.0),
            border_width: 10.0,
            ..style
        };
        let fixed = compute_fixed_rect(
            &content_box_with_border,
            800.0,
            600.0,
            LayoutRect {
                x: 0.0,
                y: 0.0,
                width: 0.0,
                height: 0.0,
            },
            false,
        );
        assert_eq!((fixed.width, fixed.height), (420.0, 320.0));

        let static_position = compute_fixed_rect(
            &Style {
                position: WPos::Fixed,
                width: WDim::Px(50.0),
                height: WDim::Px(50.0),
                ..Style::default()
            },
            800.0,
            600.0,
            LayoutRect {
                x: 58.0,
                y: 101.2,
                width: 50.0,
                height: 50.0,
            },
            false,
        );
        assert_eq!((static_position.x, static_position.y), (58.0, 101.2));

        let fixed_margin = compute_fixed_rect(
            &Style {
                position: WPos::Fixed,
                top: WDim::Px(0.0),
                margin: w3cos_std::style::Edges::all(50.0),
                width: WDim::Px(196.0),
                height: WDim::Px(196.0),
                ..Style::default()
            },
            800.0,
            600.0,
            LayoutRect {
                x: 58.0,
                y: 0.0,
                width: 196.0,
                height: 196.0,
            },
            false,
        );
        assert_eq!((fixed_margin.x, fixed_margin.y), (58.0, 50.0));
    }

