    #[test]
    fn decorated_inline_text_does_not_enlarge_the_forced_break_strut() {
        let text_style = Style {
            display: WDisp::Inline,
            font_size: 20.0,
            line_height: 1.2,
            line_height_is_normal: false,
            border_width: 10.0,
            padding: w3cos_std::style::Edges {
                top: WSpacing::Px(5.0),
                bottom: WSpacing::Px(5.0),
                ..w3cos_std::style::Edges::ZERO
            },
            ..Style::default()
        };
        let root = Component::row(
            Style {
                display: WDisp::Flex,
                font_size: 20.0,
                line_height: 1.2,
                line_height_is_normal: false,
                ..Style::default()
            },
            vec![
                Component::text("One", text_style.clone()),
                Component::text(
                    "\u{2028}",
                    Style {
                        display: WDisp::Inline,
                        font_size: 20.0,
                        line_height: 1.2,
                        width: WDim::Px(0.0),
                        height: WDim::Px(24.0),
                        ..Style::default()
                    },
                ),
                Component::text("Two", text_style),
            ],
        );
        let rect = |y, height, width| LayoutRect {
            x: 0.0,
            y,
            width,
            height,
        };
        // The decorated em box starts 15px above its content top. Its
        // content starts at half-leading=2; the line strut still starts at 0.
        let mut layout = vec![
            (rect(0.0, 48.0, 200.0), 0),
            (rect(-13.0, 50.0, 60.0), 1),
            (rect(24.0, 0.0, 0.0), 2),
            (rect(11.0, 50.0, 60.0), 3),
        ];
        project_forced_break_lines(&mut layout, &root);
        assert_eq!(
            layout[3].0.y, 11.0,
            "the second decorated em box must remain on the 24px line strut"
        );
        assert_eq!(
            layout[0].0.height, 48.0,
            "inline decoration overflow must not enlarge the parent's auto height"
        );
    }

