    #[test]
    fn trailing_preserved_newline_keeps_inline_content_box_height() {
        for line_height in [1.2, 2.0] {
            let inline = Style {
                display: WDisp::Inline,
                font_size: 16.0,
                line_height,
                ..Style::default()
            };
            let root = Component::row(
                Style {
                    display: WDisp::Block,
                    font_size: 16.0,
                    line_height,
                    ..Style::default()
                },
                vec![Component::row(
                    inline.clone(),
                    vec![
                        Component::text("text ", inline.clone()),
                        Component::text(
                            "  \n",
                            Style {
                                white_space: WWhiteSpace::Pre,
                                ..inline.clone()
                            },
                        ),
                    ],
                )],
            );
            let layout = compute(&root, 800.0, 600.0).unwrap();
            let rect = |index| layout.iter().find(|(_, i)| *i == index).unwrap().0;
            assert!(
                (rect(1).height - 16.0).abs() < 0.01,
                "inline content box acquired half-leading: {layout:?}"
            );
            // Chromium141 line-height-oracle-v1922: unitless 16px/1.2
            // occupies 19.1875px, not the computed CSS serialization 19.2px.
            let expected_strut = if line_height == 1.2 { 19.1875 } else { 32.0 };
            assert!(
                (rect(0).height - expected_strut).abs() < 0.01,
                "containing block lost its line strut: {layout:?}"
            );
        }
    }

    #[test]
    fn pre_newline_between_flattened_inline_text_leaves_starts_next_line() {
        let inline = Style {
            display: WDisp::Inline,
            font_size: 20.0,
            line_height: 1.0,
            ..Style::default()
        };
        let pre = Style {
            white_space: WWhiteSpace::Pre,
            ..inline.clone()
        };
        let root = Component::row(
            Style {
                display: WDisp::Flex,
                float: WFloat::Left,
                font_size: 20.0,
                line_height: 1.0,
                border_width: 3.0,
                ..Style::default()
            },
            vec![Component::text("x\n", pre), Component::text("x", inline)],
        );
        let layout = compute(&root, 800.0, 600.0).unwrap();
        let rect = |index| layout.iter().find(|(_, item)| *item == index).unwrap().0;
        assert!(
            (rect(2).x - rect(1).x).abs() < 0.01,
            "following text did not restart at inline start: {layout:?}"
        );
        assert!(
            rect(2).y >= rect(1).y + 19.0,
            "following text did not start the next line: {layout:?}"
        );
        assert!(
            (rect(0).width - rect(1).width - 6.0).abs() < 0.01,
            "float retained both lines' widths: {layout:?}"
        );
        assert!(
            (rect(0).height - 46.0).abs() < 0.01,
            "float omitted the trailing border: {layout:?}"
        );
    }

    #[test]
    fn nested_bdo_overrides_remain_on_one_inline_line() {
        use w3cos_dom::{Document, stylesheet};
        stylesheet::clear_rules();
        let mut document = Document::new();
        let block = document.create_element("div");
        let outer = document.create_element("bdo");
        outer.set_attribute(&mut document, "dir", "ltr");
        let inner = document.create_element("bdo");
        inner.set_attribute(&mut document, "dir", "rtl");
        let first = document.create_text_node("A ");
        let middle = document.create_text_node(" B ");
        let last = document.create_text_node(" C");
        inner.append_child(&mut document, middle);
        outer.append_child(&mut document, first);
        outer.append_child(&mut document, inner);
        outer.append_child(&mut document, last);
        block.append_child(&mut document, outer);
        document.body().append_child(&mut document, block);

        assert_eq!(document.computed_style_for(outer.id).display, WDisp::Inline);
        assert_eq!(document.computed_style_for(inner.id).display, WDisp::Inline);
        assert_eq!(
            document.computed_style_for(inner.id).unicode_bidi,
            w3cos_std::style::UnicodeBidi::BidiOverride
        );

        let root = document.to_component_tree();
        let flat = pre_flatten(&root);
        let mut layout = compute(&root, 800.0, 600.0).unwrap();
        project_auto_height_bfc_float_heights(&mut layout, &root, &flat, 800.0, 600.0);
        let text = flat
            .iter()
            .filter_map(|node| match &node.kind {
                ComponentKind::Text { content } => Some(content.as_str()),
                _ => None,
            })
            .collect::<String>();
        assert_eq!(text, "A \u{00a0}BC");
        assert_eq!(
            layout.len(),
            3,
            "nested bidi boxes split the inline line: {layout:?}"
        );
        let text_rect = layout.iter().find(|(_, index)| *index == 2).unwrap().0;
        assert!(
            text_rect.width > 39.0,
            "reordered space collapsed in layout: {layout:?}"
        );
    }

    #[test]
    fn forced_break_inside_a_split_inline_box_restarts_at_the_containing_block_edge() {
        // `#parent` is `display: inline`, so the break it contains belongs to
        // the containing block's inline formatting context. The continuation
        // must start at that context's content left edge (8), not at the
        // fragment origin of the inline box (82.38).
        let inline_style = || Style {
            display: WDisp::Inline,
            font_size: 16.0,
            font_family: Some("Ahem".into()),
            line_height: 1.2,
            line_height_is_normal: false,
            ..Style::default()
        };
        let inline_text = |content: &str| Component::text(content, inline_style());
        let forced_break = || {
            Component::text(
                "\u{2028}",
                Style {
                    width: WDim::Px(0.0),
                    height: WDim::Px(19.1875),
                    ..inline_style()
                },
            )
        };
        let root = Component::boxed(
            Style {
                display: WDisp::Block,
                font_size: 16.0,
                font_family: Some("Ahem".into()),
                line_height: 1.2,
                line_height_is_normal: false,
                padding: w3cos_std::style::Edges {
                    left: WSpacing::Px(8.0),
                    ..w3cos_std::style::Edges::ZERO
                },
                ..Style::default()
            },
            vec![
                inline_text("Filler Text"),
                Component::row(
                    inline_style(),
                    vec![forced_break(), inline_text("Filler Text")],
                ),
            ],
        );
        let rect = |x, y, width, height| LayoutRect {
            x,
            y,
            width,
            height,
        };
        let mut layouts = vec![
            (rect(0.0, 0.0, 800.0, 57.6), 0),
            (rect(8.0, 1.0, 176.0, 16.0), 1),
            (rect(188.0, 1.0, 176.0, 35.1875), 2),
            (rect(188.0, 0.0, 0.0, 19.1875), 3),
            (rect(188.0, 20.1875, 176.0, 16.0), 4),
        ];
        project_forced_break_lines(&mut layouts, &root);
        assert!(
            (layouts[4].0.x - 8.0).abs() < 0.001,
            "continuation restarted at the inline box ({})",
            layouts[4].0.x
        );
        // Pinned Ahem browser control: floored upper leading 1px plus
        // a 19.1875px used strut, not the computed CSS float 19.2px.
        assert!((layouts[4].0.y - 20.1875).abs() < 0.001,
            "continuation origin {} must preserve used line-height precision", layouts[4].0.y);
        assert!(
            (layouts[3].0.x - 188.0).abs() < 0.001,
            "the break marker is not a fragment"
        );
    }

    #[test]
    fn forced_break_inside_an_inline_block_keeps_the_inline_block_edge() {
        // An inline-block owns its line boxes, so the same break geometry
        // resolves against the inline-block's own content edge (100) and
        // must not be pulled back to the outer block's edge (0).
        let inline_style = || Style {
            display: WDisp::Inline,
            font_size: 16.0,
            font_family: Some("Ahem".into()),
            line_height: 1.2,
            line_height_is_normal: false,
            ..Style::default()
        };
        let forced_break = || {
            Component::text(
                "\u{2028}",
                Style {
                    width: WDim::Px(0.0),
                    height: WDim::Px(19.1875),
                    ..inline_style()
                },
            )
        };
        let root = Component::boxed(
            Style {
                display: WDisp::Block,
                font_size: 16.0,
                font_family: Some("Ahem".into()),
                line_height: 1.2,
                line_height_is_normal: false,
                ..Style::default()
            },
            vec![Component::boxed(
                Style {
                    display: WDisp::InlineBlock,
                    width: WDim::Px(200.0),
                    font_size: 16.0,
                    font_family: Some("Ahem".into()),
                    line_height: 1.2,
                    line_height_is_normal: false,
                    ..Style::default()
                },
                vec![
                    forced_break(),
                    Component::text("Filler Text", inline_style()),
                ],
            )],
        );
        let rect = |x, y, width, height| LayoutRect {
            x,
            y,
            width,
            height,
        };
        let mut layouts = vec![
            (rect(0.0, 0.0, 800.0, 40.0), 0),
            (rect(100.0, 0.0, 200.0, 20.0), 1),
            (rect(100.0, 0.0, 0.0, 19.1875), 2),
            (rect(100.0, 20.1875, 176.0, 16.0), 3),
        ];
        project_forced_break_lines(&mut layouts, &root);
        assert!(
            (layouts[3].0.x - 100.0).abs() < 0.001,
            "was {}",
            layouts[3].0.x
        );
        assert!((layouts[3].0.y - 20.1875).abs() < 0.001,
            "inline-block continuation origin {}", layouts[3].0.y);
    }

