    #[test]
    fn forced_break_aligns_each_inline_block_line_before_continuing() {
        let wrapper = |alignment| {
            Component::row(
                Style {
                    display: WDisp::InlineBlock,
                    align_self: alignment,
                    font_size: 20.0,
                    line_height: 1.0,
                    ..Style::default()
                },
                vec![Component::canvas(
                    300,
                    150,
                    Style {
                        display: WDisp::InlineBlock,
                        width: WDim::Px(80.0),
                        height: WDim::Px(40.0),
                        ..Style::default()
                    },
                )],
            )
        };
        let row = || {
            vec![
                wrapper(WAlignSelf::Baseline),
                wrapper(WAlignSelf::FlexStart),
                wrapper(WAlignSelf::Center),
                wrapper(WAlignSelf::FlexEnd),
            ]
        };
        let mut children = row();
        children.push(Component::text(
            "\u{2028}",
            Style {
                display: WDisp::Inline,
                ..Style::default()
            },
        ));
        children.extend(row());
        let root = Component::row(
            Style {
                display: WDisp::Flex,
                width: WDim::Px(784.0),
                font_size: 20.0,
                line_height: 1.0,
                font_family: Some("Ahem".into()),
                ..Style::default()
            },
            children,
        );
        let rect = |x, y, width, height| LayoutRect {
            x,
            y,
            width,
            height,
        };
        let mut layouts = vec![(rect(8.0, 8.0, 784.0, 168.0), 0)];
        for (base, y) in [(1, 8.0), (10, 92.0)] {
            for column in 0..4 {
                let index = base + column * 2;
                let x = 8.0 + column as f32 * 140.0;
                layouts.push((rect(x, y, 120.0, 84.0), index));
                layouts.push((rect(x + 20.0, y + 20.0, 80.0, 40.0), index + 1));
            }
            if base == 1 {
                layouts.push((rect(8.0, 92.0, 0.0, 0.0), 9));
            }
        }
        project_forced_break_inline_block_alignment(&mut layouts, &root);
        project_forced_break_lines(&mut layouts, &root);
        project_forced_break_inline_block_alignment(&mut layouts, &root);
        let y = |index| layouts.iter().find(|(_, item)| *item == index).unwrap().0.y;
        assert_eq!([y(1), y(3), y(5), y(7)], [8.0, 8.0, 18.0, 18.0]);
        assert_eq!([y(10), y(12), y(14), y(16)], [102.0, 102.0, 112.0, 112.0]);
    }

    #[test]
    fn trailing_embedded_forced_break_continues_at_the_owner_line_origin() {
        let style = Style { display: WDisp::Inline, font_size: 16.0,
            font_family: Some("Ahem".into()), line_height: 1.2, ..Style::default() };
        let root = Component::row(
            Style { display: WDisp::Block, font_size: 16.0,
                font_family: Some("Ahem".into()), line_height: 1.2, ..Style::default() },
            vec![Component::text("Filler Text\u{2028}", style.clone()),
                Component::text("Filler Text", style)],
        );
        let rect = |x, y, width, height| LayoutRect { x, y, width, height };
        let mut layouts = vec![(rect(8.0, 50.0, 784.0, 19.1875), 0),
            (rect(8.0, 51.0, 176.0, 16.0), 1),
            (rect(184.0, 51.0, 176.0, 16.0), 2)];
        project_forced_break_lines(&mut layouts, &root);
        assert_eq!(layouts[2].0.x, 8.0);
        assert!((layouts[2].0.y - 70.1875).abs() < 0.001);
        assert!((layouts[0].0.height - 38.375).abs() < 0.001);
    }

