    #[test]
    fn inline_block_forced_break_uses_last_line_baseline() {
        use w3cos_dom::{Document, stylesheet};

        stylesheet::clear_rules();
        stylesheet::register_rule("body", &[("font-size", "15px")]);
        stylesheet::register_rule("p", &[("white-space", "nowrap"), ("line-height", "5")]);
        stylesheet::register_rule(
            "span",
            &[
                ("display", "inline-block"),
                ("overflow", "visible"),
                ("line-height", "1"),
            ],
        );
        let mut document = Document::new();
        let paragraph = document.create_element("p");
        let lead = document.create_text_node("All the ");
        paragraph.append_child(&mut document, lead);
        let inline_block = document.create_element("span");
        let first_line = document.create_text_node("\u{a0}");
        inline_block.append_child(&mut document, first_line);
        let line_break = document.create_element("br");
        inline_block.append_child(&mut document, line_break);
        let last_line = document.create_text_node("words");
        inline_block.append_child(&mut document, last_line);
        paragraph.append_child(&mut document, inline_block);
        let trailing = document.create_text_node(" are aligned on the same baseline.");
        paragraph.append_child(&mut document, trailing);
        document.body().append_child(&mut document, paragraph);

        let component = document.to_component_tree();
        let layout = compute(&component, 800.0, 600.0).unwrap();
        fn text_nodes(
            component: &Component,
            index: &mut usize,
            out: &mut Vec<(usize, String, w3cos_std::style::Style)>,
        ) {
            let own = *index;
            *index += 1;
            if let ComponentKind::Text { content } = &component.kind {
                out.push((
                    own,
                    content.clone(),
                    component.style.clone(),
                ));
            }
            for child in &component.children {
                text_nodes(child, index, out);
            }
        }
        let mut texts = Vec::new();
        text_nodes(&component, &mut 0, &mut texts);
        let baseline = |needle: &str| {
            let (index, content, style) = texts
                .iter()
                .find(|(_, content, _)| content.contains(needle))
                .unwrap_or_else(|| panic!("missing {needle:?}: {texts:?}"));
            let line = content
                .split('\u{2028}')
                .position(|fragment| fragment.contains(needle))
                .expect("needle is in the selected text node");
            layout
                .iter()
                .find(|(_, candidate)| candidate == index)
                .unwrap()
                .0
                .y
                + line as f32 * style.font_size * style.line_height
                + inline_font_content_ascent(style)
        };
        let words = baseline("words");
        let outer = baseline("are aligned");
        assert!(
            (words - outer).abs() < 0.5,
            "last inline-block line must share the outside baseline: words={words}, outer={outer}"
        );
        // Relative alignment alone can pass if the atomic incorrectly drags
        // the whole line down. A paragraph without that atomic has the same
        // containing strut and supplies an independent absolute anchor.
        let mut reference = Document::new();
        let paragraph = reference.create_element("p");
        let text = reference.create_text_node("All the words are aligned on the same baseline.");
        paragraph.append_child(&mut reference, text);
        reference.body().append_child(&mut reference, paragraph);
        let reference_component = reference.to_component_tree();
        let reference_layout = compute(&reference_component, 800.0, 600.0).unwrap();
        let mut reference_texts = Vec::new();
        text_nodes(&reference_component, &mut 0, &mut reference_texts);
        let (index, _, style) = &reference_texts[0];
        // The single block Text leaf keeps a line-box rect; inline Text
        // leaves already have font-content rects. Compare rendered baselines,
        // not incompatible IR origins (the block adds signed half-leading).
        let reference_baseline = reference_layout.iter()
            .find(|(_, candidate)| candidate == index).unwrap().0.y
            + inline_font_baseline_from_line_top(style, style.font_size * style.line_height);
        assert!((outer - reference_baseline).abs() < 0.5,
            "atomic must not displace the containing strut: outer={outer}, reference={reference_baseline}");
        stylesheet::clear_rules();
    }

    #[test]
    fn anonymous_inline_line_items_preserve_negative_margin_wrapping() {
        use w3cos_dom::{Document, stylesheet};

        fn image(
            document: &mut Document,
            width_class: &str,
            margin_class: Option<&str>,
        ) -> w3cos_dom::Element {
            let image = document.create_element("img");
            image.class_list_add(document, width_class);
            if let Some(margin_class) = margin_class {
                image.class_list_add(document, margin_class);
            }
            image
        }

        fn host_height(
            flat: &[FlatNodeInfo<'_>],
            layout: &[(LayoutRect, usize)],
            host_id: u64,
        ) -> f32 {
            let index = flat
                .iter()
                .position(|node| {
                    matches!(node.on_click, EventAction::NativeHost { id, .. } if *id == host_id)
                })
                .expect("native host component");
            layout
                .iter()
                .find_map(|(rect, candidate)| (*candidate == index).then_some(rect.height))
                .expect("native host layout")
        }

        stylesheet::clear_rules();
        stylesheet::register_rule(
            ".line",
            &[
                ("width", "40px"),
                ("font-family", "Ahem"),
                ("font-size", "10px"),
                ("line-height", "1"),
            ],
        );
        stylesheet::register_rule("img", &[("height", "6px")]);
        stylesheet::register_rule(".w1", &[("width", "1ch")]);
        stylesheet::register_rule(".w2", &[("width", "2ch")]);
        stylesheet::register_rule(".w4", &[("width", "4ch")]);
        stylesheet::register_rule(".w5", &[("width", "5ch")]);
        stylesheet::register_rule(".neg1", &[("margin-left", "-1ch")]);

        let mut document = Document::new();
        let one_line = document.create_element("div");
        one_line.class_list_add(&mut document, "line");
        let first = image(&mut document, "w4", None);
        let second = image(&mut document, "w1", Some("neg1"));
        one_line.append_child(&mut document, first);
        one_line.append_child(&mut document, second);

        let two_lines = document.create_element("div");
        two_lines.class_list_add(&mut document, "line");
        let first = image(&mut document, "w4", None);
        let second = image(&mut document, "w2", Some("neg1"));
        two_lines.append_child(&mut document, first);
        two_lines.append_child(&mut document, second);

        document.body().append_child(&mut document, one_line);
        document.body().append_child(&mut document, two_lines);

        let overwide = document.create_element("div");
        overwide.class_list_add(&mut document, "line");
        let first = image(&mut document, "w5", None);
        let second = document.create_element("span");
        second.style_mut(&mut document).set_property("margin-left", "-3ch");
        second.set_text_content(&mut document, "123");
        overwide.append_child(&mut document, first);
        overwide.append_child(&mut document, second);
        document.body().append_child(&mut document, overwide);

        let component = document.to_component_tree();
        let flat = pre_flatten(&component);
        let layout = compute(&component, 800.0, 600.0).unwrap();
        assert_eq!(
            host_height(&flat, &layout, one_line.id.as_u32() as u64),
            10.0,
            "40px + (10px - 10px) stays on one 10px line: {component:#?}"
        );
        assert_eq!(
            host_height(&flat, &layout, two_lines.id.as_u32() as u64),
            20.0,
            "40px + (20px - 10px) wraps to two 10px lines: layout={layout:?}; {component:#?}"
        );
        assert_eq!(
            host_height(&flat, &layout, overwide.id.as_u32() as u64),
            20.0,
            "an overwide first image followed by zero outer-advance text must wrap: layout={layout:?}; {component:#?}"
        );
        stylesheet::clear_rules();
    }

    #[test]
    fn unbroken_inline_word_preserves_negative_outer_advance() {
        use w3cos_dom::Document;
        for property in ["margin-left", "margin-right"] {
          for margin in ["-60px", "-4em", "-50%"] {
            let mut document = Document::new();
            let host = document.create_element("div");
            host.style_mut(&mut document).set_property("width", "120px");
            host.style_mut(&mut document).set_property("font", "15px/1 Ahem");
            let before = document.create_text_node("x x x x");
            let span = document.create_element("span");
            span.style_mut(&mut document).set_property(property, margin);
            span.set_text_content(&mut document, "x");
            let after = document.create_text_node("x x x x x x");
            host.append_child(&mut document, before);
            host.append_child(&mut document, span);
            host.append_child(&mut document, after);
            document.body().append_child(&mut document, host);
            let root = document.to_component_tree();
            let flat = pre_flatten(&root);
            let host_index = flat.iter().position(|node| matches!(node.on_click,
                EventAction::NativeHost { id, .. } if *id == host.id.as_u32() as u64)).unwrap();
            let layouts = compute(&root, 800.0, 600.0).unwrap();
            let rect = layouts.iter().find(|(_, index)| *index == host_index).unwrap().0;
            assert_eq!(rect.height, 30.0,
                "negative advance beyond an unbroken word width must survive, {property}={margin}");
          }
        }
    }

    #[test]
    fn ahem_zero_outer_width_inline_image_stays_on_the_first_line() {
        use w3cos_dom::{Document, stylesheet};

        stylesheet::clear_rules();
        stylesheet::register_rule(
            ".line",
            &[
                ("width", "4ch"),
                ("font-family", "Ahem"),
                ("font-size", "10px"),
                ("line-height", "1"),
            ],
        );
        stylesheet::register_rule("img", &[("height", "0.6em")]);
        stylesheet::register_rule(".w1", &[("width", "1ch")]);
        stylesheet::register_rule(".w2", &[("width", "2ch")]);
        stylesheet::register_rule(".w4", &[("width", "4ch")]);
        stylesheet::register_rule(".neg1", &[("margin-left", "-1ch")]);

        let mut document = Document::new();
        let mut hosts = Vec::new();
        for second_width in ["w1", "w2"] {
            let host = document.create_element("div");
            host.class_list_add(&mut document, "line");
            let first = document.create_element("img");
            first.class_list_add(&mut document, "w4");
            let second = document.create_element("img");
            second.class_list_add(&mut document, second_width);
            second.class_list_add(&mut document, "neg1");
            host.append_child(&mut document, first);
            host.append_child(&mut document, second);
            document.body().append_child(&mut document, host);
            hosts.push(host.id.as_u32() as u64);
        }

        let component = document.to_component_tree();
        let flat = pre_flatten(&component);
        let layout = compute(&component, 800.0, 600.0).unwrap();
        let rect = |id| {
            let index = flat.iter().position(|node| {
                matches!(node.on_click, EventAction::NativeHost { id: host, .. } if *host == id)
            }).unwrap();
            layout
                .iter()
                .find_map(|(rect, candidate)| (*candidate == index).then_some(*rect))
                .unwrap()
        };
        assert_eq!(
            rect(hosts[0]).width,
            40.0,
            "Ahem 1ch is one 10px glyph cell"
        );
        assert_eq!(
            rect(hosts[0]).height,
            10.0,
            "zero-width second margin box should not wrap"
        );
        assert_eq!(
            rect(hosts[1]).height,
            20.0,
            "positive-width second margin box should wrap"
        );
        stylesheet::clear_rules();
    }

