    #[test]
    fn font_relative_image_cross_size_derives_auto_inline_and_float_width() {
        let source = "w3cos-font-relative-cross-size-fixture.png";
        let image = image::RgbaImage::from_pixel(15, 15, image::Rgba([0, 128, 0, 255]));
        let mut bytes = Cursor::new(Vec::new());
        image::DynamicImage::ImageRgba8(image)
            .write_to(&mut bytes, image::ImageFormat::Png)
            .unwrap();
        crate::image_loader::decode_and_install(source, &bytes.into_inner()).unwrap();
        for height in [WDim::Em(3.0), WDim::Rem(2.8125)] {
            let style = Style {
                font_size: 15.0,
                height,
                ..Style::default()
            };
            assert_eq!(
                image_intrinsic_size(source, &style, Some(90.0)),
                (45.0, 45.0)
            );
            for float in [WFloat::None, WFloat::Left] {
                let layout = compute(
                    &Component::boxed(
                        Style {
                            display: WDisp::Block,
                            width: WDim::Px(90.0),
                            ..Style::default()
                        },
                        vec![Component::image(
                            source,
                            Style {
                                display: if float == WFloat::None {
                                    WDisp::Inline
                                } else {
                                    WDisp::Block
                                },
                                float,
                                ..style.clone()
                            },
                        )],
                    ),
                    800.0,
                    600.0,
                )
                .unwrap();
                let image = layout.iter().find(|(_, index)| *index == 1).unwrap().0;
                assert_eq!(
                    (image.width, image.height),
                    (45.0, 45.0),
                    "{height:?}/{float:?}"
                );
            }
        }
        crate::image_loader::invalidate(source);
    }

    #[test]
    fn decoded_image_intrinsics_drive_auto_size_and_preserve_aspect_ratio() {
        let source = "browser-layout-intrinsic.png";
        let image = image::RgbaImage::from_pixel(4, 2, image::Rgba([1, 2, 3, 255]));
        let mut bytes = Cursor::new(Vec::new());
        image::DynamicImage::ImageRgba8(image)
            .write_to(&mut bytes, image::ImageFormat::Png)
            .unwrap();
        crate::image_loader::decode_and_install(source, &bytes.into_inner()).unwrap();

        let kind = ComponentKind::Image {
            src: source.to_string(),
        };
        assert_eq!(leaf_intrinsic_size(&kind, &Style::default()), (4.0, 2.0));
        assert_eq!(
            leaf_intrinsic_size(
                &kind,
                &Style {
                    width: WDim::Px(40.0),
                    ..Style::default()
                },
            ),
            (40.0, 20.0)
        );
        assert_eq!(
            leaf_intrinsic_size(
                &kind,
                &Style {
                    height: WDim::Px(10.0),
                    ..Style::default()
                },
            ),
            (20.0, 10.0)
        );
        assert_eq!(
            leaf_intrinsic_size(
                &kind,
                &Style {
                    width: WDim::Px(0.0),
                    min_width: WDim::Px(100.0),
                    ..Style::default()
                },
            ),
            (100.0, 50.0)
        );
        let layout = compute(
            &Component::boxed(
                Style {
                    display: WDisp::Block,
                    width: WDim::Px(800.0),
                    ..Style::default()
                },
                vec![Component::image(
                    source,
                    Style {
                        display: WDisp::Inline,
                        ..Style::default()
                    },
                )],
            ),
            800.0,
            600.0,
        )
        .unwrap();
        let image = layout.iter().find(|(_, index)| *index == 1).unwrap().0;
        assert_eq!((image.width, image.height), (4.0, 2.0));
        let constrained = compute(
            &Component::boxed(
                Style {
                    display: WDisp::Block,
                    width: WDim::Px(800.0),
                    ..Style::default()
                },
                vec![Component::image(
                    source,
                    Style {
                        display: WDisp::Inline,
                        width: WDim::Em(0.0),
                        min_width: WDim::Em(6.25),
                        ..Style::default()
                    },
                )],
            ),
            800.0,
            600.0,
        )
        .unwrap();
        let constrained = constrained.iter().find(|(_, index)| *index == 1).unwrap().0;
        assert_eq!((constrained.width, constrained.height), (100.0, 50.0));
        crate::image_loader::invalidate(source);
    }

