    #[test]
    fn non_replaced_inline_height_constraints_do_not_enlarge_the_containing_line() {
        for leaf in [false, true] {
            let tree = |minimum, maximum| {
                let style = Style {
                    display: WDisp::Inline,
                    font_size: 20.0,
                    line_height: 1.0,
                    line_height_is_normal: false,
                    min_height: minimum,
                    max_height: maximum,
                    ..Style::default()
                };
                let inline = if leaf {
                    Component::text("A", style)
                } else {
                    Component::boxed(
                        style,
                        vec![Component::text(
                            "A",
                            Style {
                                display: WDisp::Inline,
                                font_size: 20.0,
                                line_height: 1.0,
                                line_height_is_normal: false,
                                ..Style::default()
                            },
                        )],
                    )
                };
                Component::boxed(
                    Style {
                        display: WDisp::Block,
                        width: WDim::Px(200.0),
                        ..Style::default()
                    },
                    vec![inline],
                )
            };
            let control = compute(&tree(WDim::Auto, WDim::Auto), 800.0, 600.0).unwrap();
            for (minimum, maximum) in [
                (WDim::Px(100.0), WDim::Auto),
                (WDim::Auto, WDim::Px(0.0)),
            ] {
                let constrained = compute(&tree(minimum, maximum), 800.0, 600.0).unwrap();
                assert_eq!(
                    constrained, control,
                    "leaf={leaf}, min={minimum:?}, max={maximum:?}"
                );
            }
        }
    }

