    #[test]
    fn nested_inline_runs_share_the_tallest_line_baseline() {
        let outer = Style {
            display: WDisp::Inline,
            font_size: 16.0,
            line_height: 25.0 / 16.0,
            margin: w3cos_std::style::Edges {
                left: WSpacing::Px(1.0),
                right: WSpacing::Px(1.0),
                top: WSpacing::Px(1.0),
                bottom: WSpacing::Px(1.0),
            },
            padding: w3cos_std::style::Edges {
                left: WSpacing::Px(1.0),
                right: WSpacing::Px(1.0),
                top: WSpacing::Px(1.0),
                bottom: WSpacing::Px(1.0),
            },
            ..Style::default()
        };
        let short = Style {
            display: WDisp::Inline,
            font_size: 16.0,
            line_height: 25.0 / 16.0,
            ..Style::default()
        };
        let tall = Style {
            display: WDisp::Inline,
            font_size: 16.0,
            line_height: 30.0 / 16.0,
            ..Style::default()
        };
        let root = Component::row(
            Style {
                display: WDisp::Block,
                width: WDim::Px(500.0),
                ..Style::default()
            },
            vec![Component::row(
                outer,
                vec![
                    Component::text("Filler Text ", short.clone()),
                    Component::text("Filler Text", tall),
                    Component::text(" Filler Text", short),
                ],
            )],
        );
        let layout = compute(&root, 800.0, 600.0).unwrap();
        let y = |index| {
            layout
                .iter()
                .find(|(_, candidate)| *candidate == index)
                .unwrap()
                .0
                .y
        };
        assert!(
            (y(2) - y(3)).abs() < 0.01,
            "nested inline baselines: {layout:?}"
        );
        assert!(
            (y(4) - y(3)).abs() < 0.01,
            "nested inline baselines: {layout:?}"
        );
    }

