    #[test]
    fn parsed_relative_clear_bfc_preserves_its_visual_offset_through_body() {
        use crate::html_parser_host::InertParserScriptHost;
        use crate::html_parser_state::StreamingDocumentParser;
        use std::rc::Rc;

        crate::dom::reset_document();
        crate::jsdom::reset_bridge();
        let mut parser = StreamingDocumentParser::new_with_script_host(
            Rc::new(InertParserScriptHost),
            "https://example.test/relative-clear.html",
        )
        .unwrap();
        parser
            .write("<!doctype html><body><p>Preceding flow</p>\
            <div style='font:100px/1 Ahem;overflow:auto;width:200px;float:left;min-height:200px'>XXX</div>\
            <div style='font:100px/1 Ahem;overflow:auto;width:200px;clear:left;height:200px;position:relative;top:-200px'>XX</div></body>")
            .unwrap();
        parser.finish().unwrap();
        let root = crate::dom::to_component_tree();
        let flat = pre_flatten(&root);
        let layout = compute(&root, 800.0, 600.0).unwrap();
        let floating = flat
            .iter()
            .position(|node| node.style.float == WFloat::Left)
            .unwrap();
        let cleared = flat
            .iter()
            .position(|node| node.style.clear == WClear::Left)
            .unwrap();
        let rect = |index| layout.iter().find(|(_, item)| *item == index).unwrap().0;
        assert!((rect(cleared).y - rect(floating).y).abs() < 0.01);
    }

