    #[test]
    fn leading_block_overlaps_or_avoids_a_float_by_formatting_context() {
        let layout = |overflow| {
            compute(
                &Component::boxed(
                    Style {
                        display: WDisp::Block,
                        width: WDim::Px(200.0),
                        height: WDim::Px(200.0),
                        ..Style::default()
                    },
                    vec![
                        Component::boxed(
                            Style {
                                display: WDisp::Block,
                                float: WFloat::Left,
                                width: WDim::Px(50.0),
                                height: WDim::Px(50.0),
                                ..Style::default()
                            },
                            Vec::new(),
                        ),
                        Component::boxed(
                            Style {
                                display: WDisp::Block,
                                overflow,
                                width: WDim::Px(50.0),
                                height: WDim::Px(50.0),
                                ..Style::default()
                            },
                            Vec::new(),
                        ),
                    ],
                ),
                800.0,
                600.0,
            )
            .unwrap()
        };

        let visible = layout(WOverflow::Visible);
        let visible_float = visible.iter().find(|(_, index)| *index == 1).unwrap().0;
        let visible_block = visible.iter().find(|(_, index)| *index == 2).unwrap().0;
        assert_eq!(visible_block.y, visible_float.y);
        assert_eq!(visible_block.x, visible_float.x);

        let hidden = layout(WOverflow::Hidden);
        let hidden_float = hidden.iter().find(|(_, index)| *index == 1).unwrap().0;
        let hidden_block = hidden.iter().find(|(_, index)| *index == 2).unwrap().0;
        assert_eq!(hidden_block.y, hidden_float.y);
        assert_eq!(hidden_block.x, hidden_float.x + hidden_float.width);
    }

    #[test]
    fn auto_width_overflow_bfc_uses_the_available_float_band() {
        for (width, min_width) in [
            (WDim::Auto, WDim::Auto),
            (WDim::Px(300.0), WDim::Auto),
            (WDim::Auto, WDim::Px(250.0)),
            (WDim::Auto, WDim::Percent(90.0)),
        ] {
            let root = Component::boxed(
                Style {
                    display: WDisp::Block,
                    width: WDim::Px(300.0),
                    ..Style::default()
                },
                vec![
                    Component::boxed(
                        Style {
                            display: WDisp::Block,
                            float: WFloat::Left,
                            width: WDim::Px(100.0),
                            height: WDim::Px(100.0),
                            ..Style::default()
                        },
                        vec![],
                    ),
                    Component::boxed(
                        Style {
                            display: WDisp::Block,
                            overflow: WOverflow::Hidden,
                            width,
                            min_width,
                            ..Style::default()
                        },
                        vec![Component::boxed(
                            Style {
                                display: WDisp::InlineBlock,
                                width: WDim::Px(150.0),
                                height: WDim::Px(50.0),
                                ..Style::default()
                            },
                            vec![],
                        )],
                    ),
                ],
            );
            let layout = compute(&root, 800.0, 600.0).unwrap();
            let get = |index| layout.iter().find(|(_, i)| *i == index).unwrap().0;
            if matches!(width, WDim::Auto) && matches!(min_width, WDim::Auto) {
                assert_eq!(get(2).width, 200.0);
                assert_eq!(get(2).x, get(1).x + get(1).width);
                assert_eq!(get(2).y, get(1).y);
            } else {
                assert_eq!(get(2).width, 300.0);
                assert!(get(2).y >= get(1).y + get(1).height);
            }
        }
    }

