    #[test]
    fn auto_nested_html_table_reflows_its_tracks_into_the_float_band() {
        let html_table_style = |width, spacing| {
            let mut style = Style {
                display: WDisp::Table,
                width,
                border_spacing_x: spacing,
                border_spacing_y: spacing,
                ..Style::default()
            };
            style
                .custom_properties
                .get_or_insert_with(Default::default)
                .insert("--w3cos-internal-html-table-element".into(), "1".into());
            style
        };
        let grid = |children| {
            vec![Component::boxed(
                Style {
                    display: WDisp::TableRowGroup,
                    ..Style::default()
                },
                vec![Component::row(
                    Style {
                        display: WDisp::TableRow,
                        ..Style::default()
                    },
                    vec![Component::boxed(
                        Style {
                            display: WDisp::TableCell,
                            ..Style::default()
                        },
                        children,
                    )],
                )],
            )]
        };
        let span = |width| {
            Component::boxed(
                Style {
                    display: WDisp::InlineBlock,
                    width: WDim::Px(width),
                    height: WDim::Px(50.0),
                    align_self: WAlignSelf::FlexEnd,
                    ..Style::default()
                },
                vec![],
            )
        };
        for (spacing, span_width) in [(0.0, 150.0), (2.0, 150.0), (0.0, 300.0)] {
            let mut line_style = Style {
                display: WDisp::Flex,
                width: WDim::Percent(100.0),
                flex_wrap: WWrap::Wrap,
                ..Style::default()
            };
            line_style
                .custom_properties
                .get_or_insert_with(Default::default)
                .insert(
                    "--w3cos-internal-inline-formatting-context".into(),
                    "1".into(),
                );
            let nested = Component::boxed(
                html_table_style(WDim::Auto, spacing),
                grid(vec![Component::row(
                    line_style,
                    vec![
                        span(span_width),
                        Component::text(
                            " ",
                            Style {
                                display: WDisp::Inline,
                                ..Style::default()
                            },
                        ),
                        span(span_width),
                    ],
                )]),
            );
            let root = Component::boxed(
                html_table_style(WDim::Px(300.0), 0.0),
                grid(vec![
                    Component::boxed(
                        Style {
                            display: WDisp::Block,
                            float: WFloat::Left,
                            width: WDim::Px(100.0),
                            height: WDim::Px(100.0),
                            ..Style::default()
                        },
                        vec![],
                    ),
                    nested,
                ]),
            );
            let layout = compute(&root, 800.0, 600.0).unwrap();
            let get = |index| layout.iter().find(|(_, i)| *i == index).unwrap().0;
            if span_width > 200.0 {
                assert!(get(5).width >= 300.0);
                assert!(get(5).y >= get(4).y + get(4).height);
                continue;
            }
            assert_eq!(
                (get(5).width, get(5).height),
                (200.0, 100.0 + 2.0 * spacing)
            );
            assert_eq!((get(5).x, get(5).y), (get(4).x + get(4).width, get(4).y));
            assert_eq!(get(8).width, 200.0 - 2.0 * spacing);
            assert_eq!(
                (get(10).x, get(10).y),
                (get(5).x + spacing, get(5).y + spacing)
            );
            assert_eq!((get(12).x, get(12).y), (get(10).x, get(10).y + 50.0));
        }
    }

    #[test]
    fn anonymous_inline_bfc_reflows_wrapped_boxes_into_the_float_band() {
        let mut inline_style = Style {
            display: WDisp::Flex,
            overflow: WOverflow::Hidden,
            flex_wrap: WWrap::Wrap,
            align_items: w3cos_std::style::AlignItems::Baseline,
            ..Style::default()
        };
        inline_style
            .custom_properties
            .get_or_insert_with(Default::default)
            .insert(
                "--w3cos-internal-inline-formatting-context".into(),
                "1".into(),
            );
        let span = || {
            Component::boxed(
                Style {
                    display: WDisp::InlineBlock,
                    width: WDim::Px(150.0),
                    height: WDim::Px(50.0),
                    align_self: WAlignSelf::FlexEnd,
                    ..Style::default()
                },
                vec![],
            )
        };
        for display in [WDisp::Block, WDisp::TableCell] {
            let root = Component::boxed(
                Style {
                    display,
                    width: WDim::Px(300.0),
                    ..Style::default()
                },
                vec![
                    Component::boxed(
                        Style {
                            display: WDisp::Block,
                            float: WFloat::Left,
                            width: WDim::Px(100.0),
                            height: WDim::Px(100.0),
                            ..Style::default()
                        },
                        vec![],
                    ),
                    Component::row(
                        inline_style.clone(),
                        vec![
                            span(),
                            Component::text(
                                " ",
                                Style {
                                    display: WDisp::Inline,
                                    ..Style::default()
                                },
                            ),
                            span(),
                        ],
                    ),
                ],
            );
            let layout = compute(&root, 800.0, 600.0).unwrap();
            let get = |index| layout.iter().find(|(_, i)| *i == index).unwrap().0;
            assert_eq!(
                (get(2).width, get(2).height),
                (200.0, 100.0),
                "parent={display:?}"
            );
            assert_eq!((get(2).x, get(2).y), (get(1).x + get(1).width, get(1).y));
            assert_eq!((get(3).x, get(3).y), (get(2).x, get(2).y));
            assert_eq!((get(5).x, get(5).y), (get(2).x, get(2).y + 50.0));
        }
    }

    #[test]
    fn opposite_floats_try_the_top_band_before_advancing_below() {
        for first_side in [WFloat::Left, WFloat::Right] {
            for (width, clear, relative_top) in [
                (200.0, WClear::None, 0.0),
                (250.0, WClear::None, 0.0),
                (200.0, WClear::Both, 0.0),
                (200.0, WClear::None, 20.0),
            ] {
                let second_side = if first_side == WFloat::Left {
                    WFloat::Right
                } else {
                    WFloat::Left
                };
                let root = Component::boxed(
                    Style {
                        display: WDisp::Block,
                        width: WDim::Px(300.0),
                        ..Style::default()
                    },
                    vec![
                        Component::boxed(
                            Style {
                                display: WDisp::Block,
                                float: first_side,
                                position: WPos::Relative,
                                top: WDim::Px(relative_top),
                                width: WDim::Px(100.0),
                                height: WDim::Px(100.0),
                                ..Style::default()
                            },
                            vec![],
                        ),
                        Component::boxed(
                            Style {
                                display: WDisp::Block,
                                float: second_side,
                                clear,
                                width: WDim::Px(width),
                                height: WDim::Px(50.0),
                                ..Style::default()
                            },
                            vec![Component::boxed(
                                Style {
                                    display: WDisp::Block,
                                    width: WDim::Px(150.0),
                                    height: WDim::Px(50.0),
                                    ..Style::default()
                                },
                                vec![],
                            )],
                        ),
                    ],
                );
                let mut layout = vec![
                    (
                        LayoutRect {
                            x: 0.0,
                            y: 0.0,
                            width: 300.0,
                            height: 150.0,
                        },
                        0,
                    ),
                    (
                        LayoutRect {
                            x: if first_side == WFloat::Left {
                                0.0
                            } else {
                                200.0
                            },
                            y: relative_top,
                            width: 100.0,
                            height: 100.0,
                        },
                        1,
                    ),
                    (
                        LayoutRect {
                            x: 0.0,
                            y: 100.0,
                            width,
                            height: 50.0,
                        },
                        2,
                    ),
                    (
                        LayoutRect {
                            x: 0.0,
                            y: 100.0,
                            width: 150.0,
                            height: 50.0,
                        },
                        3,
                    ),
                ];
                project_simple_float_margin_boxes(&mut layout, &root, 800.0, 600.0);
                let y = if width > 200.0 || clear != WClear::None {
                    100.0
                } else {
                    0.0
                };
                let x = if second_side == WFloat::Left {
                    0.0
                } else {
                    300.0 - width
                };
                assert_eq!(
                    (layout[2].0.x, layout[2].0.y),
                    (x, y),
                    "first={first_side:?} width={width} clear={clear:?} relative={relative_top}"
                );
                assert_eq!((layout[3].0.x, layout[3].0.y), (x, y));
            }
        }
    }

    #[test]
