    #[test]
    fn authored_flex_flow_root_respects_float_item_authored_margin() {
        let root = Component::row(
            Style {
                display: WDisp::InlineFlex,
                flex_direction: WDir::RowReverse,
                width: WDim::Px(30.0),
                height: WDim::Px(40.0),
                border_width: 1.0,
                ..Style::default()
            },
            vec![
                Component::row(
                    Style {
                        display: WDisp::Block,
                        float: WFloat::Right,
                        width: WDim::Px(7.0),
                        height: WDim::Px(8.0),
                        border_width: 1.0,
                        margin: w3cos_std::style::Edges {
                            top: w3cos_std::style::Spacing::Px(1.0),
                            bottom: w3cos_std::style::Spacing::Px(1.0),
                            left: w3cos_std::style::Spacing::Px(2.0),
                            right: w3cos_std::style::Spacing::Px(3.0),
                        },
                        ..Style::default()
                    },
                    vec![],
                ),
                Component::row(
                    Style {
                        display: WDisp::FlowRoot,
                        flex_grow: 1.0,
                        height: WDim::Px(15.0),
                        border_width: 1.0,
                        ..Style::default()
                    },
                    vec![],
                ),
            ],
        );
        let layout = compute(&root, 800.0, 600.0).unwrap();
        let rect = |index| layout.iter().find(|(_, node)| *node == index).unwrap().0;
        assert_eq!(rect(2).width, 16.0);
        assert_eq!(rect(2).x, 1.0);
        assert_eq!(rect(1).x, 19.0);
    }

