    #[test]
    fn first_table_bfc_uses_the_band_released_by_the_shorter_float() {
        for (long_side, short_side) in [
            (WFloat::Left, WFloat::Left),
            (WFloat::Left, WFloat::Right),
            (WFloat::Right, WFloat::Left),
            (WFloat::Right, WFloat::Right),
        ] {
            let floating = |side, height| {
                Component::boxed(
                    Style {
                        display: WDisp::Block,
                        float: side,
                        width: WDim::Px(100.0),
                        height: WDim::Px(height),
                        ..Style::default()
                    },
                    vec![],
                )
            };
            let root = Component::boxed(
                Style {
                    display: WDisp::Block,
                    width: WDim::Px(300.0),
                    ..Style::default()
                },
                vec![
                    floating(long_side, 20.0),
                    floating(short_side, 6.0),
                    Component::boxed(
                        Style {
                            display: WDisp::Table,
                            width: WDim::Px(150.0),
                            height: WDim::Px(10.0),
                            ..Style::default()
                        },
                        vec![],
                    ),
                ],
            );
            let layout = compute(&root, 800.0, 600.0).unwrap();
            let table = layout.iter().find(|(_, index)| *index == 3).unwrap().0;
            assert_eq!(table.y, 6.0, "sides={long_side:?}/{short_side:?}");
            assert_eq!(
                table.x,
                if long_side == WFloat::Left {
                    100.0
                } else {
                    0.0
                }
            );
        }
    }

    #[test]
    fn block_table_avoids_a_float_and_keeps_parent_height_when_it_cannot_fit() {
        for (width, margin_percent) in [(0.0, 0.0), (100.0, 0.0), (100.0, 10.0)] {
            let root = Component::boxed(
                Style {
                    display: WDisp::Block,
                    width: WDim::Px(width),
                    ..Style::default()
                },
                vec![
                    Component::boxed(
                        Style {
                            display: WDisp::Block,
                            float: WFloat::Left,
                            width: WDim::Px(20.0),
                            height: WDim::Px(20.0),
                            ..Style::default()
                        },
                        Vec::new(),
                    ),
                    Component::boxed(
                        Style {
                            display: WDisp::Table,
                            width: WDim::Px(50.0),
                            height: WDim::Px(20.0),
                            margin: w3cos_std::style::Edges {
                                left: WSpacing::Percent(margin_percent),
                                ..Default::default()
                            },
                            ..Style::default()
                        },
                        Vec::new(),
                    ),
                ],
            );
            let layout = compute(&root, 800.0, 600.0).unwrap();
            let parent = layout.iter().find(|(_, index)| *index == 0).unwrap().0;
            let table = layout.iter().find(|(_, index)| *index == 2).unwrap().0;
            if width == 0.0 {
                assert_eq!(table.y, 20.0);
                assert!(parent.height >= table.y + table.height);
            } else {
                assert_eq!(table.y, 0.0);
                // The margin's normal offset is already inside the float's
                // occupied band; Chromium places the border edge at 20px,
                // not at float edge + 10% again.
                assert_eq!(table.x, 20.0);
            }
        }
    }

