    #[test]
    fn hidden_table_parts_suppress_collapsed_cell_layout_widths() {
        use w3cos_std::style::BorderLineStyle;
        for display in [
            WDisp::TableRow,
            WDisp::TableRowGroup,
            WDisp::TableColumn,
            WDisp::TableColumnGroup,
        ] {
            let hidden = Style {
                display,
                border_collapse: true,
                border_styles: [Some(BorderLineStyle::Hidden); 4],
                ..Style::default()
            };
            let cell = Component::boxed(
                Style {
                    display: WDisp::TableCell,
                    border_width: 3.0,
                    border_collapse: true,
                    border_styles: [Some(BorderLineStyle::Solid); 4],
                    ..Style::default()
                },
                vec![],
            );
            let row = Component::row(
                if display == WDisp::TableRow {
                    hidden.clone()
                } else {
                    Style {
                        display: WDisp::TableRow,
                        border_collapse: true,
                        ..Style::default()
                    }
                },
                vec![cell],
            );
            let children = if display == WDisp::TableRowGroup {
                vec![Component::boxed(hidden, vec![row])]
            } else if matches!(display, WDisp::TableColumn | WDisp::TableColumnGroup) {
                vec![Component::boxed(hidden, vec![]), row]
            } else {
                vec![row]
            };
            let mut table = Component::boxed(
                Style {
                    display: WDisp::Table,
                    border_collapse: true,
                    ..Style::default()
                },
                children,
            );
            resolve_collapsed_table_layout_borders(&mut table);
            fn check(component: &Component, display: WDisp) {
                if component.style.display == WDisp::TableCell {
                    for side in 0..4 {
                        assert_eq!(
                            collapsed_layout_edge_width(&component.style, side),
                            0.0,
                            "{display:?} side {side}"
                        );
                    }
                }
                for child in &component.children {
                    check(child, display);
                }
            }
            check(&table, display);
        }
    }

