    #[test]
    fn text_only_atomic_inline_keeps_its_authored_line_box_height() {
        let typography = Style {
            font_size: 30.0,
            line_height: 4.0,
            line_height_is_normal: false,
            ..Style::default()
        };
        let root = Component::row(
            Style {
                display: WDisp::Block,
                float: WFloat::Left,
                ..typography.clone()
            },
            vec![Component::text("12345678", Style {
                display: WDisp::InlineBlock,
                max_width: WDim::Em(4.0),
                ..typography
            })],
        );
        let layout = compute(&root, 800.0, 600.0).unwrap();
        let parent = layout.iter().find(|(_, index)| *index == 0).unwrap().0;
        let atomic = layout.iter().find(|(_, index)| *index == 1).unwrap().0;
        // An atomic inline's principal box contains its line-height, unlike
        // the em-only paint rectangle of a passive non-replaced inline.
        assert_eq!(atomic.height, 120.0, "atomic={atomic:?}, parent={parent:?}");
        assert_eq!(atomic.y, parent.y, "same typography shares the line baseline");
    }

    #[test]
    fn block_table_wrapper_em_margins_use_the_parent_font() {
        let em_margin = |value| w3cos_std::style::Edges {
            top: WSpacing::Em(value),
            right: WSpacing::Em(value),
            bottom: WSpacing::Em(value),
            left: WSpacing::Em(value),
        };
        let float_margin = w3cos_std::style::Edges {
            top: WSpacing::Em(0.5),
            right: WSpacing::Em(1.0),
            bottom: WSpacing::Em(0.5),
            left: WSpacing::Em(1.0),
        };
        let child = |display, float, margin| {
            Component::boxed(
                Style {
                    display,
                    float,
                    font_size: 32.0,
                    margin,
                    ..Style::default()
                },
                vec![Component::text("same", Style::default())],
            )
        };
        let layout_for = |child| {
            let root = Component::boxed(
                Style {
                    display: WDisp::Block,
                    width: WDim::Px(800.0),
                    font_size: 16.0,
                    ..Style::default()
                },
                vec![child],
            );
            compute(&root, 800.0, 600.0)
                .unwrap()
                .into_iter()
                .find(|(_, index)| *index == 1)
                .unwrap()
                .0
        };

        let table = layout_for(child(WDisp::Table, WFloat::None, em_margin(1.0)));
        let floating = layout_for(child(WDisp::Block, WFloat::Left, float_margin));
        assert_eq!(table.y, 16.0);
        assert_eq!(table.y, floating.y);
        assert_eq!(table.x, 32.0);
        assert_eq!(table.x, floating.x);
    }

