    #[test]
    fn collapsed_row_border_matches_equivalent_row_group_border_geometry() {
        let cell = || {
            Component::boxed(
                Style {
                    display: WDisp::TableCell,
                    border_collapse: true,
                    border_width: 10.0,
                    ..Style::default()
                },
                vec![Component::text("cell", Style::default())],
            )
        };
        let row = |border_width: f32| {
            Component::row(
                Style {
                    display: WDisp::TableRow,
                    border_collapse: true,
                    border_width,
                    ..Style::default()
                },
                vec![cell(), cell(), cell()],
            )
        };
        let group = |border_width: f32, rows: Vec<Component>| {
            Component::boxed(
                Style {
                    display: WDisp::TableRowGroup,
                    border_collapse: true,
                    border_width,
                    ..Style::default()
                },
                rows,
            )
        };
        let table = |groups: Vec<Component>| {
            Component::boxed(
                Style {
                    display: WDisp::Table,
                    border_collapse: true,
                    border_spacing_x: 2.0,
                    border_spacing_y: 2.0,
                    ..Style::default()
                },
                groups,
            )
        };

        let row_border = compute(
            &table(vec![group(0.0, vec![row(0.0), row(20.0), row(0.0)])]),
            800.0,
            600.0,
        )
        .unwrap();
        let group_border = compute(
            &table(vec![
                group(0.0, vec![row(0.0)]),
                group(20.0, vec![row(0.0)]),
                group(0.0, vec![row(0.0)]),
            ]),
            800.0,
            600.0,
        )
        .unwrap();

        let row_table = row_border.iter().find(|(_, index)| *index == 0).unwrap().0;
        let group_table = group_border
            .iter()
            .find(|(_, index)| *index == 0)
            .unwrap()
            .0;
        assert_eq!(row_table, group_table);
        for (row_cell, group_cell) in [3, 5, 7, 10, 12, 14, 17, 19, 21]
            .into_iter()
            .zip([3, 5, 7, 11, 13, 15, 19, 21, 23])
        {
            let row_rect = row_border
                .iter()
                .find(|(_, index)| *index == row_cell)
                .unwrap()
                .0;
            let group_rect = group_border
                .iter()
                .find(|(_, index)| *index == group_cell)
                .unwrap()
                .0;
            for (actual, expected) in [
                (row_rect.x, group_rect.x),
                (row_rect.y, group_rect.y),
                (row_rect.width, group_rect.width),
                (row_rect.height, group_rect.height),
            ] {
                assert!(
                    (actual - expected).abs() < 0.0001,
                    "cell {row_cell}/{group_cell}: {actual} versus {expected}"
                );
            }
        }
        let row_frame = row_border.iter().find(|(_, index)| *index == 9).unwrap().0;
        let group_frame = group_border
            .iter()
            .find(|(_, index)| *index == 9)
            .unwrap()
            .0;
        assert_eq!(
            row_frame, group_frame,
            "equivalent bordered row and row group"
        );
    }

