    #[test]
    fn float_after_a_block_starts_after_the_blocks_line() {
        use crate::html_parser_host::InertParserScriptHost;
        use crate::xml_tree_builder::StreamingXmlDocumentParser;
        use std::rc::Rc;

        crate::dom::reset_document();
        crate::jsdom::reset_bridge();
        w3cos_dom::stylesheet::clear_rules();
        w3cos_dom::stylesheet::register_rule(
            "div div",
            &[("background", "blue"), ("width", "1in")],
        );
        w3cos_dom::stylesheet::register_rule("#span1", &[("background", "orange")]);
        w3cos_dom::stylesheet::register_rule(
            "#span2",
            &[
                ("background", "yellow"),
                ("float", "left"),
                ("width", "0.5in"),
            ],
        );
        crate::dom::set_html_document(false);
        crate::jsdom::set_document_content_type("application/xhtml+xml");
        let mut parser = StreamingXmlDocumentParser::from_started_navigation(
            Rc::new(InertParserScriptHost),
            "https://example.test/block-then-float.xht",
        );
        parser.write(r#"<html xmlns='http://www.w3.org/1999/xhtml'><head/><body>
            <p>Test passes if the orange stripe is below the blue stripe and the yellow stripe is on the left-hand side of the orange stripe.</p>
            <div id='div1'>
              <div>Block box</div>
              <span id='span1'>Inline box</span>
              <span id='span2'>Float</span>
            </div></body></html>"#).unwrap();
        parser.finish().unwrap();
        let root = crate::dom::to_component_tree();
        let flat = pre_flatten(&root);
        let layout = compute(&root, 800.0, 600.0).unwrap();
        w3cos_dom::stylesheet::clear_rules();
        let rect = |index| layout.iter().find(|(_, node)| *node == index).unwrap().0;
        let block = flat
            .iter()
            .enumerate()
            .find(|(_, node)| {
                node.style.width == WDim::Px(96.0) && node.style.background == Color::rgb(0, 0, 255)
            })
            .map(|(i, _)| rect(i))
            .unwrap();
        let floating = flat
            .iter()
            .enumerate()
            .find(|(_, node)| node.style.float == WFloat::Left)
            .map(|(i, _)| rect(i))
            .unwrap();
        assert!(
            (block.width - 96.0).abs() < 0.01,
            "the mixed-flow layout basis must not stretch the block's painted width: {layout:?}"
        );
        assert!(
            floating.y >= block.y + block.height - 0.01,
            "a float after a block must not occupy the block's row: block={block:?}, float={floating:?}, layout={layout:?}"
        );
    }

    #[test]
    fn block_after_a_floated_inline_starts_after_the_anonymous_line() {
        use crate::html_parser_host::InertParserScriptHost;
        use crate::xml_tree_builder::StreamingXmlDocumentParser;
        use std::rc::Rc;

        crate::dom::reset_document();
        crate::jsdom::reset_bridge();
        w3cos_dom::stylesheet::clear_rules();
        w3cos_dom::stylesheet::register_rule("span", &[("background", "blue")]);
        w3cos_dom::stylesheet::register_rule(
            "#floating",
            &[
                ("background", "orange"),
                ("float", "left"),
                ("width", "0.5in"),
            ],
        );
        w3cos_dom::stylesheet::register_rule("#block", &[("background", "yellow")]);
        crate::dom::set_html_document(false);
        crate::jsdom::set_document_content_type("application/xhtml+xml");
        let mut parser = StreamingXmlDocumentParser::from_started_navigation(
            Rc::new(InertParserScriptHost),
            "https://example.test/inline-float-then-block.xht",
        );
        parser.write(r#"<html xmlns='http://www.w3.org/1999/xhtml'><head/><body>
            <p>Test passes if the orange stripe is on the left-hand side of the blue stripe and both stripes are above the yellow bar.</p>
            <div>
              <span>Inline box</span>
              <div id='floating'>Float</div>
              <div id='block'>Block box</div>
            </div></body></html>"#).unwrap();
        parser.finish().unwrap();
        let root = crate::dom::to_component_tree();
        let flat = pre_flatten(&root);
        let layout = compute(&root, 800.0, 600.0).unwrap();
        w3cos_dom::stylesheet::clear_rules();
        let rect = |index| layout.iter().find(|(_, node)| *node == index).unwrap().0;
        let floating = flat
            .iter()
            .enumerate()
            .find(|(_, node)| node.style.float == WFloat::Left)
            .map(|(i, _)| rect(i))
            .unwrap();
        let block = flat
            .iter()
            .enumerate()
            .find(|(_, node)| {
                node.style.background == Color::rgb(255, 255, 0)
                    && node.style.display == WDisp::Block
            })
            .map(|(i, _)| rect(i))
            .unwrap();
        assert!(
            block.y >= floating.y + floating.height - 0.01,
            "the following block starts after this anonymous line: float={floating:?}, block={block:?}, layout={layout:?}"
        );
    }

    #[test]
    fn collapsed_separator_after_a_full_generated_word_adds_no_empty_line() {
        let word = Component::row(
            Style {
                display: WDisp::InlineFlex,
                width: WDim::Px(100.0),
                height: WDim::Px(20.0),
                custom_properties: Some(HashMap::from([(
                    "--w3cos-internal-unbroken-inline-word".to_string(),
                    "1".to_string(),
                )])),
                ..Style::default()
            },
            vec![],
        );
        for available in [100.0, 50.0] {
            let mut word = word.clone();
            word.style.flex_shrink = 0.0;
            let root = Component::row(
                Style {
                    display: WDisp::Flex,
                    flex_wrap: WWrap::Wrap,
                    align_items: WAlign::Baseline,
                    width: WDim::Px(available),
                    ..Style::default()
                },
                vec![
                    word.clone(),
                    Component::text(
                        " ",
                        Style {
                            display: WDisp::Inline,
                            ..Style::default()
                        },
                    ),
                    word,
                ],
            );
            let layout = compute(&root, 200.0, 200.0).unwrap();
            assert_eq!(
                layout.iter().find(|(_, index)| *index == 3).unwrap().0.y,
                20.0,
                "width {available}"
            );
            assert_eq!(
                layout
                    .iter()
                    .find(|(_, index)| *index == 0)
                    .unwrap()
                    .0
                    .height,
                40.0,
                "width {available}"
            );
        }
    }

    #[test]
    fn collapsed_separator_after_a_full_plain_word_adds_no_empty_line() {
        let word = Component::text(
            "XXXXX",
            Style {
                display: WDisp::Inline,
                font_size: 20.0,
                line_height: 1.0,
                ..Style::default()
            },
        );
        let width = component_min_content_width(&word);
        let mut style = Style {
            display: WDisp::Flex,
            flex_wrap: WWrap::Wrap,
            align_items: WAlign::Baseline,
            width: WDim::Px(width),
            font_size: 20.0,
            line_height: 1.0,
            ..Style::default()
        };
        style
            .custom_properties
            .get_or_insert_with(Default::default)
            .insert(
                "--w3cos-internal-inline-formatting-context".into(),
                "1".into(),
            );
        let mut children = vec![word.clone()];
        for _ in 1..5 {
            children.push(Component::text(
                " ",
                Style {
                    display: WDisp::Inline,
                    font_size: 20.0,
                    line_height: 1.0,
                    ..Style::default()
                },
            ));
            children.push(word.clone());
        }
        let root = Component::row(style, children);
        let layout = compute(&root, 800.0, 600.0).unwrap();
        let rect = |index| layout.iter().find(|(_, id)| *id == index).unwrap().0;
        for line in 1..5 {
            assert!(
                (rect(1 + line * 2).y - rect(1).y - line as f32 * 20.0).abs() < 0.1,
                "a full plain word's trailing space must collapse: {layout:?}"
            );
        }
        assert!((rect(0).height - 100.0).abs() < 0.1, "{layout:?}");
    }

    #[test]
    fn fractional_line_origin_does_not_round_a_wrapped_row_backward() {
        let inline = Style {
            display: WDisp::Inline,
            font_size: 20.0,
            line_height: 1.0,
            ..Style::default()
        };
        let root = Component::row(
            Style {
                display: WDisp::Flex,
                width: WDim::Px(100.0),
                font_size: 20.0,
                line_height: 1.0,
                align_items: WAlign::Baseline,
                ..Style::default()
            },
            (0..5)
                .map(|_| Component::text("XXXXX", inline.clone()))
                .collect(),
        );
        let mut layouts = vec![(
            LayoutRect {
                x: 8.0,
                y: 51.2,
                width: 100.0,
                height: 100.0,
            },
            0,
        )];
        layouts.extend((0..5).map(|line| {
            (
                LayoutRect {
                    x: 8.0,
                    y: 51.2 + line as f32 * 20.0,
                    width: 100.0,
                    height: 20.0,
                },
                line + 1,
            )
        }));
        align_inline_block_last_line_baselines(&mut layouts, &root);
        for line in 0..5 {
            assert!(
                (layouts[line + 1].0.y - (51.2 + line as f32 * 20.0)).abs() < 0.01,
                "a line boundary must not snap backward: {layouts:?}"
            );
        }
    }

