    #[test]
    fn undecorated_inline_table_exports_first_line_before_a_hidden_block() {
        use crate::font_face::{FontFace, FontRegistry, FontSource};
        const OWNER: u64 = u64::MAX - 3464;
        const FAMILY: &str = "w3cos-inline-table-baseline-probe";
        struct ProbeFont;
        impl Drop for ProbeFont {
            fn drop(&mut self) {
                FontRegistry::global().clear_owner(OWNER);
            }
        }
        let _font = ProbeFont;
        FontRegistry::global()
            .register_for_owner(
                OWNER,
                FontFace {
                    family: FAMILY.to_string(),
                    src: FontSource::Bytes(include_bytes!("../assets/Inter-Regular.ttf").to_vec()),
                    ..Default::default()
                },
            )
            .expect("the baseline regression's embedded font must load");
        for outside_size in [20.0, 30.0] {
            for lines in [1, 2] {
                for hidden_first in [false, true] {
                    let style = |display, font_size| {
                        let mut style = Style {
                            display,
                            font_family: Some(FAMILY.to_string()),
                            font_size,
                            ..Style::default()
                        };
                        // Match the loaded face's content height instead of
                        // assuming host fallback or unregistered Ahem metrics.
                        style.line_height = inline_font_height(&style) / font_size;
                        style
                    };
                    let inline =
                        |content, size| Component::text(content, style(WDisp::Inline, size));
                    let mut hidden_style = style(WDisp::Block, 20.0);
                    hidden_style.visibility = WVisibility::Hidden;
                    let hidden = Component::text("x", hidden_style);
                    let visible = inline("bcd", 20.0);
                    let inside_style = style(WDisp::Inline, 20.0);
                    let outside_style = style(WDisp::Inline, outside_size);
                    let inside_height = inline_font_height(&inside_style);
                    let outside_height = inline_font_height(&outside_style);
                    let ascent_delta = inline_font_content_ascent(&outside_style)
                        - inline_font_content_ascent(&inside_style);
                    let cell_children = if hidden_first {
                        vec![hidden, visible]
                    } else {
                        vec![visible, hidden]
                    };
                    let table = Component::boxed(
                        style(WDisp::InlineTable, 20.0),
                        vec![Component::row(
                            style(WDisp::TableRow, 20.0),
                            vec![Component::boxed(
                                style(WDisp::TableCell, 20.0),
                                cell_children,
                            )],
                        )],
                    );
                    let rect = |y, height| LayoutRect {
                        x: 0.0,
                        y,
                        width: 20.0,
                        height,
                    };
                    let mut children = Vec::new();
                    let mut layouts = vec![(rect(16.0, lines as f32 * 60.0), 0)];
                    for line in 0..lines {
                        children.extend([
                            inline("a", outside_size),
                            table.clone(),
                            inline("e", outside_size),
                        ]);
                        let first = 1 + line * 7;
                        let y = 16.0 + line as f32 * 60.0;
                        // The preceding line layout allocates the larger
                        // outside font's ascent before baseline export.
                        let table_y = y + ascent_delta;
                        layouts.extend([
                            (rect(y + inside_height, outside_height), first),
                            (rect(table_y, inside_height * 2.0), first + 1),
                            (rect(table_y, inside_height * 2.0), first + 2),
                            (rect(table_y, inside_height * 2.0), first + 3),
                            (rect(table_y, inside_height), first + 4),
                            (rect(table_y + inside_height, inside_height), first + 5),
                            (rect(y + inside_height, outside_height), first + 6),
                        ]);
                    }
                    let root = Component::row(style(WDisp::Block, 20.0), children);
                    let flat = pre_flatten(&root);
                    align_inline_table_first_row_baselines(&mut layouts, &flat);
                    for line in 0..lines {
                        let first = 1 + line * 7;
                        let y = 16.0 + line as f32 * 60.0;
                        let expected_top = y;
                        for index in [first, first + 6] {
                            assert!(
                                (layouts[index].0.y - expected_top).abs() < 0.0001,
                                "outside{outside_size} lines{lines} hidden_first{hidden_first}: {layouts:?}"
                            );
                        }
                        let table_y = y + ascent_delta;
                        assert_eq!(layouts[first + 4].0.y, table_y);
                        assert_eq!(
                            layouts[first + 5].0.y,
                            table_y + inside_height,
                            "cell content keeps its flow position"
                        );
                    }
                    let once = layouts.clone();
                    align_inline_table_first_row_baselines(&mut layouts, &flat);
                    assert_eq!(layouts, once, "alignment must be idempotent");
                }
            }
        }
    }

    #[test]
    fn inline_table_uses_its_first_cell_text_as_the_sibling_baseline() {
        let inline = |content| {
            Component::text(
                content,
                Style {
                    display: WDisp::Inline,
                    ..Style::default()
                },
            )
        };
        let table = Component::row(
            Style {
                display: WDisp::InlineTable,
                ..Style::default()
            },
            vec![Component::text(
                "bcd",
                Style {
                    display: WDisp::TableCell,
                    padding: w3cos_std::style::Edges::xy(0.0, 9.0),
                    border_top_width: Some(4.0),
                    ..Style::default()
                },
            )],
        );
        let root = Component::row(
            Style {
                display: WDisp::Block,
                ..Style::default()
            },
            vec![inline("a"), table, inline("e")],
        );
        let flat = pre_flatten(&root);
        let rect = |y, height| LayoutRect {
            x: 0.0,
            y,
            width: 0.0,
            height,
        };
        let mut layout = vec![
            (rect(0.0, 0.0), 0),
            (rect(28.6, 18.0), 1),
            (rect(30.0, 90.0), 2),
            (rect(48.0, 45.2), 3),
            (rect(28.6, 18.0), 4),
        ];

        align_inline_table_first_row_baselines(&mut layout, &flat);

        assert!((layout[1].0.y - 62.6).abs() < 0.01);
        assert!((layout[4].0.y - 62.6).abs() < 0.01);
    }

