    #[test]
    fn table_and_inline_table_preserve_both_lines_around_br() {
        use w3cos_dom::Document;

        let height = |display: &str| {
            let mut document = Document::new();
            let table = document.create_element("div");
            table
                .style_mut(&mut document)
                .set_property("display", display);
            table.style_mut(&mut document).set_property("width", "10em");
            let first = document.create_text_node("Test");
            let br = document.create_element("br");
            let second = document.create_text_node("Test");
            table.append_child(&mut document, first);
            table.append_child(&mut document, br);
            table.append_child(&mut document, second);
            document.body().append_child(&mut document, table);
            let root = document.to_component_tree();
            let flat = pre_flatten(&root);
            let layout = compute(&root, 800.0, 600.0).unwrap();
            let index = flat
                .iter()
                .enumerate()
                .find(|(_, node)| {
                    matches!(node.style.display, WDisplay::Table | WDisplay::InlineTable)
                })
                .unwrap()
                .0;
            layout
                .iter()
                .find(|(_, item)| *item == index)
                .unwrap()
                .0
                .height
        };

        let block = height("table");
        let inline = height("inline-table");
        assert!(
            block > 30.0 && inline > 30.0 && (block - inline).abs() < 0.01,
            "a forced break needs two equal table lines: block={block}, inline={inline}"
        );
    }

    #[test]
    fn parsed_table_and_inline_table_preserve_both_lines_around_br() {
        use crate::html_parser_host::InertParserScriptHost;
        use crate::html_parser_state::StreamingDocumentParser;
        use std::rc::Rc;

        let height = |display: &str| {
            crate::dom::reset_document();
            crate::jsdom::reset_bridge();
            let mut parser = StreamingDocumentParser::new_with_script_host(
                Rc::new(InertParserScriptHost),
                "https://example.test/table-br.html",
            )
            .unwrap();
            parser
                .write(&format!(
                    "<!doctype html><html><body>\
                <div style='display:{display};width:10em;background:green;color:white'>\
                Test<br />Test</div></body></html>"
                ))
                .unwrap();
            parser.finish().unwrap();
            let root = crate::dom::to_component_tree();
            let flat = pre_flatten(&root);
            let layout = compute(&root, 800.0, 600.0).unwrap();
            let expected_display = if display == "table" {
                WDisplay::Table
            } else {
                WDisplay::InlineTable
            };
            let index = flat
                .iter()
                .enumerate()
                .find(|(_, node)| node.style.display == expected_display)
                .unwrap()
                .0;
            layout
                .iter()
                .find(|(_, item)| *item == index)
                .unwrap()
                .0
                .height
        };

        let block = height("table");
        let inline = height("inline-table");
        assert!(
            block > 30.0 && inline > 30.0 && (block - inline).abs() < 0.01,
            "parsed forced break needs two equal table lines: block={block}, inline={inline}"
        );
    }

