    #[test]
    fn following_paragraph_uses_in_flow_block_bottom_after_intervening_float() {
        use crate::html_parser_host::InertParserScriptHost;
        use crate::html_parser_state::StreamingDocumentParser;
        use std::rc::Rc;

        crate::dom::reset_document();
        crate::jsdom::reset_bridge();
        let mut parser = StreamingDocumentParser::new_with_script_host(
            Rc::new(InertParserScriptHost),
            "https://example.test/float-following-flow.html",
        )
        .unwrap();
        parser
            .write(
                "<!doctype html><body>\
            <p style='height:20px;margin-top:0;margin-bottom:90px'></p>\
            <p style='float:left;width:200px;height:100px;margin:0;background:orange'></p>\
            <p style='clear:none;height:100px;margin-top:75px;background:green'></p>\
            <p>Following text</p></body>",
            )
            .unwrap();
        parser.finish().unwrap();
        let root = crate::dom::to_component_tree();
        let flat = pre_flatten(&root);
        let layout = compute(&root, 800.0, 600.0).unwrap();
        let rect = |index| layout.iter().find(|(_, item)| *item == index).unwrap().0;
        let green = flat
            .iter()
            .enumerate()
            .find(|(_, node)| node.style.background.g > 0 && node.style.background.r == 0)
            .map(|(index, _)| rect(index))
            .unwrap();
        let following = flat.iter().enumerate().find(|(_, node)|
            matches!(node.kind, ComponentKind::Text { content } if content == "Following text"))
            .map(|(index, _)| rect(index)).unwrap();
        assert!(
            (following.y - (green.y + green.height + 16.0)).abs() < 0.01,
            "green={green:?}, following={following:?}, layout={layout:?}"
        );
    }

