    #[test]
    fn caption_float_shrink_wraps_its_text_before_inline_sibling() {
        use crate::html_parser_host::InertParserScriptHost;
        use crate::html_parser_state::StreamingDocumentParser;
        use std::rc::Rc;

        crate::dom::reset_document();
        crate::jsdom::reset_bridge();
        let mut parser = StreamingDocumentParser::new_with_script_host(
            Rc::new(InertParserScriptHost),
            "https://example.test/caption.html",
        )
        .unwrap();
        parser
            .write(
                "<!doctype html><table><caption style='text-align:left;width:200px'>\
            <div style='float:left;border:1px solid black'>floated</div>inline\
            </caption></table>",
            )
            .unwrap();
        parser.finish().unwrap();
        let root = crate::dom::to_component_tree();
        fn first_float(component: &Component) -> Option<&Component> {
            if component.style.float == WFloat::Left {
                return Some(component);
            }
            component.children.iter().find_map(first_float)
        }
        let intrinsic = shrink_to_fit_used_width_with_available(first_float(&root).unwrap(), 200.0);
        let flat = pre_flatten(&root);
        let layout = compute(&root, 800.0, 600.0).unwrap();
        let float_index = flat
            .iter()
            .position(|node| node.style.float == WFloat::Left)
            .unwrap();
        let float_rect = layout
            .iter()
            .find(|(_, index)| *index == float_index)
            .unwrap()
            .0;
        assert!(
            float_rect.width > 20.0,
            "caption float must include its text intrinsic width, got {float_rect:?}, intrinsic={intrinsic}"
        );
        let caption_index = flat
            .iter()
            .position(|node| node.style.display == WDisp::TableCaption)
            .unwrap();
        let inline_index = flat
            .iter()
            .position(
                |node| matches!(node.kind, ComponentKind::Text { content } if content == "inline"),
            )
            .unwrap();
        let caption_rect = layout
            .iter()
            .find(|(_, index)| *index == caption_index)
            .unwrap()
            .0;
        let inline_rect = layout
            .iter()
            .find(|(_, index)| *index == inline_index)
            .unwrap()
            .0;
        assert!(
            (inline_rect.y - caption_rect.y).abs() < 0.01,
            "caption inline text must keep the block line origin: {caption_rect:?} {inline_rect:?}"
        );
    }

    #[test]
    fn floated_table_expands_past_specified_width_before_float_placement() {
        use crate::html_parser_host::InertParserScriptHost;
        use crate::html_parser_state::StreamingDocumentParser;
        use std::rc::Rc;

        crate::dom::reset_document();
        crate::jsdom::reset_bridge();
        let mut parser = StreamingDocumentParser::new_with_script_host(
            Rc::new(InertParserScriptHost),
            "https://example.test/floated-table.html",
        )
        .unwrap();
        parser
            .write(
                "<!doctype html><div style='width:300px'>\
            <div style='float:left;width:200px;height:100px'></div>\
            <div style='float:left;display:table;width:50px;height:10px'>\
              <div style='width:200px;height:100px'></div>\
            </div></div>",
            )
            .unwrap();
        parser.finish().unwrap();
        let root = crate::dom::to_component_tree();
        let flat = pre_flatten(&root);
        let layout = compute(&root, 800.0, 600.0).unwrap();
        let table_index = flat
            .iter()
            .position(|node| node.style.display == WDisp::Table && node.style.float == WFloat::Left)
            .unwrap();
        let table = layout
            .iter()
            .find(|(_, index)| *index == table_index)
            .unwrap()
            .0;
        fn floated_table(component: &Component) -> Option<&Component> {
            if component.style.display == WDisp::Table && component.style.float == WFloat::Left {
                return Some(component);
            }
            component.children.iter().find_map(floated_table)
        }
        let table_node = floated_table(&root).unwrap();
        let minimum = table_min_content_border_box_width(table_node, 300.0, 800.0, 600.0);
        assert!(
            table.width >= 200.0 - 0.01,
            "auto table layout must honor its rigid 200px content: {table:?}, intrinsic minimum={minimum}"
        );
        assert!(
            table.height >= 100.0 - 0.01,
            "specified table height must grow around taller content: {table:?}"
        );
        let first_index = flat
            .iter()
            .position(|node| node.style.float == WFloat::Left && node.style.display != WDisp::Table)
            .unwrap();
        let first = layout
            .iter()
            .find(|(_, index)| *index == first_index)
            .unwrap()
            .0;
        assert!(
            (table.x - first.x).abs() < 0.01 && (table.y - first.y - 100.0).abs() < 0.01,
            "the expanded table must wrap below the first float: first={first:?} table={table:?}"
        );
    }

