    #[test]
    fn unbroken_inline_run_places_full_width_float_below_its_text_line() {
        use crate::html_parser_host::InertParserScriptHost;
        use crate::html_parser_state::StreamingDocumentParser;
        use std::rc::Rc;

        crate::dom::reset_document();
        crate::jsdom::reset_bridge();
        let mut parser = StreamingDocumentParser::new_with_script_host(
            Rc::new(InertParserScriptHost),
            "https://example.test/float-nowrap.html",
        )
        .unwrap();
        parser
            .write(
                "<!doctype html><div style='font-size:10px;width:12ch;line-height:1'>\
            1111<nobr>2222<div style='float:left;width:12ch;height:1em'></div>3333</nobr>\
            </div>",
            )
            .unwrap();
        parser.finish().unwrap();
        let root = crate::dom::to_component_tree();
        let flat = pre_flatten(&root);
        let layout = compute(&root, 800.0, 600.0).unwrap();
        let text_y = |needle: &str| {
            let index = flat.iter().position(|node|
                matches!(node.kind, ComponentKind::Text { content } if content.contains(needle))).unwrap();
            layout.iter().find(|(_, item)| *item == index).unwrap().0.y
        };
        let float_index = flat
            .iter()
            .position(|node| node.style.float == WFloat::Left && node.style.width == WDim::Ch(12.0))
            .unwrap();
        let float_y = layout
            .iter()
            .find(|(_, item)| *item == float_index)
            .unwrap()
            .0
            .y;
        assert_eq!(
            text_y("2222"),
            text_y("3333"),
            "nowrap text around a deferred full-width float stays on one line"
        );
        assert_eq!(
            float_y,
            text_y("2222") + 10.0,
            "the deferred float follows the earlier inline line box"
        );
    }

