    #[test]
    fn negative_margin_bfc_clears_float_at_browser_computed_width() {
        use crate::html_parser_host::InertParserScriptHost;
        use crate::html_parser_state::StreamingDocumentParser;
        use std::rc::Rc;

        crate::dom::reset_document();
        crate::jsdom::reset_bridge();
        let mut parser = StreamingDocumentParser::new_with_script_host(
            Rc::new(InertParserScriptHost),
            "https://example.test/bfc-margin.html",
        )
        .unwrap();
        parser
            .write(
                "<!doctype html><div style='width:50px;margin-left:50px'>\
            <div style='float:right;clear:right;width:25px;height:50px'></div>\
            <div style='overflow:hidden;height:50px;margin-left:-50px'></div>\
            <div style='float:right;clear:right;width:25px;height:50px'></div>\
            <div style='overflow:hidden;height:50px;margin-left:-50px;width:75px'></div>\
            </div>",
            )
            .unwrap();
        parser.finish().unwrap();
        let root = crate::dom::to_component_tree();
        let flat = pre_flatten(&root);
        let layout = compute(&root, 800.0, 600.0).unwrap();
        let rect = |index: usize| layout.iter().find(|(_, item)| *item == index).unwrap().0;
        let bfcs = flat
            .iter()
            .enumerate()
            .filter(|(_, node)| node.style.resolved_overflow_x() == WOverflow::Hidden)
            .map(|(index, _)| rect(index))
            .collect::<Vec<_>>();
        let floats = flat
            .iter()
            .enumerate()
            .filter(|(_, node)| node.style.float == WFloat::Right)
            .map(|(index, _)| rect(index))
            .collect::<Vec<_>>();
        assert_eq!(bfcs.len(), 2);
        assert_eq!(floats.len(), 2);
        assert_eq!(
            (bfcs[0].x, bfcs[0].y, bfcs[0].width),
            (floats[0].x - 75.0, floats[0].y + floats[0].height, 100.0)
        );
        assert_eq!(
            (bfcs[1].x, bfcs[1].y, bfcs[1].width),
            (floats[1].x - 75.0, floats[1].y + floats[1].height, 75.0)
        );
    }

    #[test]
    fn bordered_auto_bfc_with_negative_margin_does_not_shrink_beside_float() {
        use crate::html_parser_host::InertParserScriptHost;
        use crate::html_parser_state::StreamingDocumentParser;
        use std::rc::Rc;

        for (negative_margin, must_clear) in [(30, true), (17, true), (16, false)] {
            crate::dom::reset_document();
            crate::jsdom::reset_bridge();
            let mut parser = StreamingDocumentParser::new_with_script_host(
                Rc::new(InertParserScriptHost),
                "https://example.test/bordered-bfc.html",
            )
            .unwrap();
            parser
                .write(&format!(
                    "<!doctype html><div style='display:inline-block;width:30px'>\
                <div style='float:left;width:7px;height:8px;border:1px solid;\
                    margin:1px 3px 1px 2px'></div>\
                <div style='display:flow-root;height:15px;border:1px solid;\
                    margin-left:-{negative_margin}px'></div></div>"
                ))
                .unwrap();
            parser.finish().unwrap();
            let root = crate::dom::to_component_tree();
            let flat = pre_flatten(&root);
            let layout = compute(&root, 800.0, 600.0).unwrap();
            let rect = |index: usize| layout.iter().find(|(_, item)| *item == index).unwrap().0;
            let floating = flat
                .iter()
                .enumerate()
                .find(|(_, node)| node.style.float == WFloat::Left)
                .map(|(index, _)| rect(index))
                .unwrap();
            let bfc = flat
                .iter()
                .enumerate()
                .find(|(_, node)| node.style.display == WDisplay::FlowRoot)
                .map(|(index, _)| rect(index))
                .unwrap();
            if must_clear {
                assert!(
                    bfc.y >= floating.y + floating.height + 1.0 - 0.01,
                    "margin=-{negative_margin}, float={floating:?}, bfc={bfc:?}"
                );
                assert_eq!(bfc.width, 30.0 + negative_margin as f32);
            } else {
                assert!(
                    bfc.y < floating.y + floating.height,
                    "margin=-{negative_margin}, float={floating:?}, bfc={bfc:?}"
                );
            }
        }
    }

    #[test]
    fn nested_bfc_overflow_does_not_reenter_float_exclusion_outside_parent() {
        use crate::html_parser_host::InertParserScriptHost;
        use crate::html_parser_state::StreamingDocumentParser;
        use std::rc::Rc;

        for (side, outer_margin, inner_margin) in [
            ("right", "margin-right:50px", ""),
            ("left", "margin-left:50px", "margin-left:-50px"),
        ] {
            crate::dom::reset_document();
            crate::jsdom::reset_bridge();
            let mut parser = StreamingDocumentParser::new_with_script_host(
                Rc::new(InertParserScriptHost),
                "https://example.test/nested-bfc.html",
            )
            .unwrap();
            parser
                .write(&format!(
                    "<!doctype html><div style='width:100px'>\
                <div style='float:{side};width:50px;height:50px'></div>\
                <div style='{outer_margin}'>\
                  <div style='overflow:hidden;width:100px;height:50px;{inner_margin}'></div>\
                </div></div>"
                ))
                .unwrap();
            parser.finish().unwrap();
            let root = crate::dom::to_component_tree();
            let flat = pre_flatten(&root);
            let layout = compute(&root, 800.0, 600.0).unwrap();
            let rect = |index: usize| layout.iter().find(|(_, item)| *item == index).unwrap().0;
            let floating = flat
                .iter()
                .enumerate()
                .find(|(_, node)| node.style.float != WFloat::None)
                .map(|(index, _)| rect(index))
                .unwrap();
            let (bfc_index, _) = flat
                .iter()
                .enumerate()
                .find(|(_, node)| node.style.resolved_overflow_x() == WOverflow::Hidden)
                .unwrap();
            let bfc = rect(bfc_index);
            let parent = rect(flat[bfc_index].parent.unwrap());
            assert_eq!(
                bfc.y,
                floating.y,
                "browser keeps overflow at the ordinary parent's line: side={side} float={floating:?} bfc={bfc:?}"
            );
            assert!(
                parent.y + parent.height >= bfc.y + bfc.height - 0.01,
                "auto-height parent must contain the shifted BFC: side={side} parent={parent:?} bfc={bfc:?}"
            );
            assert_eq!(parent.height, 50.0, "no extra clearance may grow the ordinary parent");
        }
    }

