    #[test]
    fn nonfitting_bfc_margin_does_not_pull_earlier_float_down() {
        use crate::html_parser_host::InertParserScriptHost;
        use crate::html_parser_state::StreamingDocumentParser;
        use std::rc::Rc;

        for (
            outer_style,
            branch_style,
            float_height,
            bfc_top,
            bfc_height,
            branch_offset,
            expected_outer_height,
        ) in [
            ("overflow:hidden;width:200px", "", 200, 200, 1, 0.0, 201.0),
            (
                "overflow:hidden;width:200px;height:200px",
                "margin-top:-50px",
                150,
                12345,
                100,
                -50.0,
                200.0,
            ),
        ] {
            crate::dom::reset_document();
            crate::jsdom::reset_bridge();
            let mut parser = StreamingDocumentParser::new_with_script_host(
                Rc::new(InertParserScriptHost),
                "https://example.test/separate-float.html",
            )
            .unwrap();
            parser
                .write(&format!(
                    "<!doctype html><div style='{outer_style}'>\
                <div style='{branch_style}'><div>\
                    <div style='float:left;width:200px;height:{float_height}px'></div>\
                </div><div style='margin-top:{bfc_top}px;overflow:hidden;\
                    width:200px;height:{bfc_height}px'></div></div></div>"
                ))
                .unwrap();
            parser.finish().unwrap();
            let root = crate::dom::to_component_tree();
            let flat = pre_flatten(&root);
            let layout = compute(&root, 800.0, 600.0).unwrap();
            let rect = |index: usize| layout.iter().find(|(_, item)| *item == index).unwrap().0;
            let owner = flat
                .iter()
                .enumerate()
                .find(|(_, node)| {
                    node.style.resolved_overflow_x() == WOverflow::Hidden
                        && node.style.width == WDim::Px(200.0)
                })
                .map(|(index, _)| rect(index))
                .unwrap();
            let floating = flat
                .iter()
                .enumerate()
                .find(|(_, node)| node.style.float == WFloat::Left)
                .map(|(index, _)| rect(index))
                .unwrap();
            let bfc = flat
                .iter()
                .enumerate()
                .find(|(_, node)| node.style.margin_lengths().top == bfc_top as f32)
                .map(|(index, _)| rect(index))
                .unwrap();
            assert_eq!(
                floating.y,
                owner.y + branch_offset,
                "outer={outer_style}, float={floating:?}, owner={owner:?}"
            );
            assert_eq!(bfc.y, floating.y + floating.height);
            assert_eq!(owner.height, expected_outer_height);
        }
    }

