    #[test]
    fn negative_clearance_after_bottom_margin_keeps_following_block_at_float_content_origin() {
        use crate::html_parser_host::InertParserScriptHost;
        use crate::html_parser_state::StreamingDocumentParser;
        use std::rc::Rc;

        crate::dom::reset_document();
        crate::jsdom::reset_bridge();
        let mut parser = StreamingDocumentParser::new_with_script_host(
            Rc::new(InertParserScriptHost),
            "https://example.test/negative-clearance-after-bottom-margin.html",
        )
        .unwrap();
        parser
            .write(
                "<!doctype html><p>Test passes</p>\
            <div style='position:relative;top:-50px;z-index:-1'>\
              <div style='float:left;width:50px;height:50px;border-top:50px solid white;background:green'></div>\
              <div style='padding-top:1px'>\
                <div style='width:100px;background:green'>\
                  <div style='margin-bottom:49px'></div>\
                  <div style='clear:left;margin-top:98px'></div>\
                </div>\
                <div style='width:100px;height:50px;background:green'></div>\
              </div>\
            </div>",
            )
            .unwrap();
        parser.finish().unwrap();
        let root = crate::dom::to_component_tree();
        let flat = pre_flatten(&root);
        let layout = compute(&root, 800.0, 600.0).unwrap();
        let rect = |index: usize| layout.iter().find(|(_, item)| *item == index).unwrap().0;
        let floating_index = flat
            .iter()
            .enumerate()
            .find(|(_, node)| node.style.float == WFloat::Left)
            .map(|(index, _)| index)
            .unwrap();
        let floating = rect(floating_index);
        let float_content_y = floating.y
            + flat[floating_index]
                .style
                .border_top_width
                .unwrap_or(flat[floating_index].style.border_width);
        let following_green = flat
            .iter()
            .enumerate()
            .filter(|(_, node)| node.style.background.g > 0 && node.style.height == WDim::Px(50.0))
            .last()
            .map(|(index, _)| rect(index))
            .unwrap();
        let cleared_parent = flat
            .iter()
            .enumerate()
            .find(|(_, node)| {
                node.style.background.g > 0
                    && node.style.width == WDim::Px(100.0)
                    && node.style.height == WDim::Auto
            })
            .map(|(index, _)| rect(index))
            .unwrap();
        assert!(
            (following_green.y - float_content_y).abs() < 0.01,
            "float={floating:?}, following={following_green:?}, layout={layout:?}"
        );
        assert!(
            (cleared_parent.height - floating.height).abs() < 0.01,
            "float={floating:?}, cleared_parent={cleared_parent:?}"
        );
    }

