    #[test]
    fn negative_block_margin_chooses_above_beside_or_below_a_float() {
        use crate::html_parser_host::InertParserScriptHost;
        use crate::html_parser_state::StreamingDocumentParser;
        use std::rc::Rc;

        for (top_margin, width, dx, dy, wrapper_height) in [
            (-75, 50, 0.0, -75.0, 60.0),
            (-75, 75, 0.0, -75.0, 60.0),
            (-25, 50, 50.0, -25.0, 60.0),
            (-25, 75, 0.0, 50.0, 110.0),
        ] {
            crate::dom::reset_document();
            crate::jsdom::reset_bridge();
            let mut parser = StreamingDocumentParser::new_with_script_host(
                Rc::new(InertParserScriptHost),
                "https://example.test/negative-bfc.html",
            )
            .unwrap();
            parser
                .write(&format!(
                    "<!doctype html><div style='float:left;width:100px;\
                border:5px solid;margin:75px 10px'>\
                <div style='float:left;width:50px;height:50px'></div>\
                <div style='overflow:hidden;height:50px;width:{width}px;\
                    margin-top:{top_margin}px'></div></div>"
                ))
                .unwrap();
            parser.finish().unwrap();
            let root = crate::dom::to_component_tree();
            let flat = pre_flatten(&root);
            let layout = compute(&root, 800.0, 600.0).unwrap();
            let rect = |index: usize| layout.iter().find(|(_, item)| *item == index).unwrap().0;
            let floating = flat
                .iter()
                .enumerate()
                .find(|(_, node)| {
                    node.style.float == WFloat::Left && node.style.width == WDim::Px(50.0)
                })
                .map(|(index, _)| rect(index))
                .unwrap();
            let bfc = flat
                .iter()
                .enumerate()
                .find(|(_, node)| node.style.resolved_overflow_x() == WOverflow::Hidden)
                .map(|(index, _)| rect(index))
                .unwrap();
            assert_eq!(
                (bfc.x, bfc.y),
                (floating.x + dx, floating.y + dy),
                "margin={top_margin}, width={width}, float={floating:?}, bfc={bfc:?}"
            );
            let wrapper = rect(
                flat.iter()
                    .enumerate()
                    .find(|(_, node)| {
                        node.style.float == WFloat::Left && node.style.width == WDim::Px(100.0)
                    })
                    .map(|(index, _)| index)
                    .unwrap(),
            );
            assert_eq!(
                wrapper.height, wrapper_height,
                "margin={top_margin}, width={width}, wrapper={wrapper:?}"
            );
        }
    }

