    #[test]
    fn atomic_inline_line_ignores_expired_or_zero_height_float_width() {
        use w3cos_dom::{Document, stylesheet};

        stylesheet::clear_rules();
        let mut document = Document::new();
        let box_node = document.create_element("div");
        for (name, value) in [
            ("width", "100px"),
            ("height", "100px"),
            ("line-height", "0"),
            ("position", "relative"),
            ("background", "red"),
        ] {
            box_node.style_mut(&mut document).set_property(name, value);
        }
        let specs = [
            ("div", "float: left; width: 20px; height: 20px"),
            ("div", "height: 30px; background: green"),
            (
                "div",
                "float: right; width: 40px; height: 20px; background: green",
            ),
            (
                "div",
                "float: right; clear: right; width: 50px; height: 50px; background: green",
            ),
            (
                "div",
                "float: left; width: 50px; height: 50px; background: green",
            ),
            (
                "span",
                "display: inline-block; width: 40px; height: 20px; background: green",
            ),
            (
                "div",
                "position: absolute; left: 40px; top: 30px; width: 20px; height: 20px; background: green",
            ),
        ];
        let mut hosts = Vec::new();
        for (tag, css) in specs {
            let child = document.create_element(tag);
            for declaration in css
                .split(';')
                .filter(|declaration| !declaration.trim().is_empty())
            {
                let (name, value) = declaration.split_once(':').unwrap();
                child
                    .style_mut(&mut document)
                    .set_property(name.trim(), value.trim());
            }
            hosts.push(child.id.as_u32() as u64);
            box_node.append_child(&mut document, child);
        }
        let box_id = box_node.id.as_u32() as u64;
        document.body().append_child(&mut document, box_node);
        let zero_float_box = document.create_element("div");
        for (name, value) in [
            ("width", "100px"),
            ("height", "100px"),
            ("line-height", "0"),
            ("position", "relative"),
            ("background", "red"),
        ] {
            zero_float_box
                .style_mut(&mut document)
                .set_property(name, value);
        }
        let zero_specs = [
            "float: left; width: 20px",
            "float: right; width: 30px; height: 50px; background: green",
            "float: right; clear: right; width: 100px; height: 50px; background: green",
            "display: inline-block; width: 50px; height: 50px; background: green",
            "position: absolute; left: 50px; top: 0; width: 20px; height: 50px; background: green",
        ];
        let mut zero_hosts = Vec::new();
        for css in zero_specs {
            let whitespace = document.create_text_node("\n  ");
            zero_float_box.append_child(&mut document, whitespace);
            let child = document.create_element("div");
            for declaration in css
                .split(';')
                .filter(|declaration| !declaration.trim().is_empty())
            {
                let (name, value) = declaration.split_once(':').unwrap();
                child
                    .style_mut(&mut document)
                    .set_property(name.trim(), value.trim());
            }
            zero_hosts.push(child.id.as_u32() as u64);
            zero_float_box.append_child(&mut document, child);
        }
        let zero_box_id = zero_float_box.id.as_u32() as u64;
        document.body().append_child(&mut document, zero_float_box);
        let tree = document.to_component_tree();
        let flat = pre_flatten(&tree);
        let layouts = compute(&tree, 800.0, 600.0).unwrap();
        let rect = |id| {
            let index = flat
                .iter()
                .position(|node| {
                    matches!(node.on_click, EventAction::NativeHost { id: host, .. }
                    if *host == id)
                })
                .unwrap_or_else(|| panic!("missing host {id}"));
            layouts
                .iter()
                .find(|(_, candidate)| *candidate == index)
                .unwrap()
                .0
        };
        let box_rect = rect(box_id);
        assert_eq!(rect(hosts[0]).y, box_rect.y);
        assert_eq!(
            rect(hosts[5]).x,
            box_rect.x,
            "box={box_rect:?}, hosts={:?}",
            hosts.iter().copied().map(rect).collect::<Vec<_>>()
        );
        let zero_box_rect = rect(zero_box_id);
        assert_eq!(rect(zero_hosts[0]).height, 0.0);
        assert_eq!(
            rect(zero_hosts[3]).x,
            zero_box_rect.x,
            "zero-height float must not indent the inline-block: {:?}",
            zero_hosts.iter().copied().map(rect).collect::<Vec<_>>()
        );
    }

