    #[test]
    fn normal_inline_inside_pre_block_can_wrap_after_a_full_line() {
        let mut document = w3cos_dom::Document::new();
        let block = document.create_element("div");
        for (name, value) in [
            ("width", "80px"),
            ("font-size", "20px"),
            ("font-family", "Ahem"),
            ("line-height", "1"),
            ("white-space", "pre"),
        ] {
            block.style_mut(&mut document).set_property(name, value);
        }
        let prefix = document.create_text_node("XXXX");
        block.append_child(&mut document, prefix);
        let span = document.create_element("span");
        span.style_mut(&mut document)
            .set_property("white-space", "normal");
        let continuation = document.create_text_node(" X");
        span.append_child(&mut document, continuation);
        block.append_child(&mut document, span);
        document.body().append_child(&mut document, block);

        let root = document.to_component_tree();
        let flat = pre_flatten(&root);
        let layout = compute(&root, 200.0, 200.0).unwrap();
        let rect = |content: &str| {
            let index = flat
                .iter()
                .position(|node| {
                    matches!(node.kind,
                ComponentKind::Text { content: text } if text == content)
                })
                .unwrap();
            layout
                .iter()
                .find(|(_, candidate)| *candidate == index)
                .unwrap()
                .0
        };
        let first = rect("XXXX");
        let next = rect(" X");
        assert_eq!(next.x, first.x, "{layout:?}");
        assert!(next.y >= first.y + 20.0, "{layout:?}");
        assert_eq!(next.width, 20.0, "{layout:?}");
    }

    #[test]
    fn nested_normal_inline_wraps_with_outer_pre_line_width() {
        let mut document = w3cos_dom::Document::new();
        let block = document.create_element("div");
        for (name, value) in [
            ("width", "80px"),
            ("font-size", "20px"),
            ("font-family", "Ahem"),
            ("line-height", "1"),
            ("white-space", "pre"),
        ] {
            block.style_mut(&mut document).set_property(name, value);
        }
        let prefix = document.create_text_node("XXXX");
        block.append_child(&mut document, prefix);
        let span = document.create_element("span");
        span.style_mut(&mut document)
            .set_property("white-space", "normal");
        let continuation = document.create_text_node(" X X X X");
        span.append_child(&mut document, continuation);
        block.append_child(&mut document, span);
        document.body().append_child(&mut document, block);

        let root = document.to_component_tree();
        let flat = pre_flatten(&root);
        let layout = compute(&root, 200.0, 200.0).unwrap();
        let text = flat
            .iter()
            .enumerate()
            .filter_map(|(index, component)| {
                let ComponentKind::Text { content } = &component.kind else {
                    return None;
                };
                let rect = layout.iter().find(|(_, candidate)| *candidate == index)?.0;
                Some((content.as_str(), rect))
            })
            .collect::<Vec<_>>();
        let prefix = text
            .iter()
            .find(|(content, _)| *content == "XXXX")
            .unwrap()
            .1;
        let continuation = text.iter().filter(|(content, _)| *content == "X")
            .map(|(_, rect)| *rect).collect::<Vec<_>>();
        assert_eq!(continuation.len(), 4, "{text:?}");
        // Original Chromium with pinned Ahem: continuation occupies two
        // normal lines, regardless of the generated text-fragment count.
        for (rect, (x, y)) in continuation.iter().zip([(8.0, 28.0), (48.0, 28.0),
            (8.0, 48.0), (48.0, 48.0)]) {
            assert_eq!((rect.x, rect.y, rect.width, rect.height), (x, y, 20.0, 20.0), "{text:?}");
            assert!(rect.y >= prefix.y + 20.0, "{text:?}");
        }
    }

    #[test]
    fn nested_normal_inline_fragments_share_outer_pre_lines() {
        let mut document = w3cos_dom::Document::new();
        let block = document.create_element("div");
        for (name, value) in [
            ("width", "80px"),
            ("font-size", "20px"),
            ("font-family", "Ahem"),
            ("line-height", "1"),
            ("white-space", "pre"),
        ] {
            block.style_mut(&mut document).set_property(name, value);
        }
        let prefix = document.create_text_node("XXXX");
        block.append_child(&mut document, prefix);
        let outer = document.create_element("span");
        outer
            .style_mut(&mut document)
            .set_property("white-space", "normal");
        let first = document.create_text_node(" X X");
        outer.append_child(&mut document, first);
        let inner = document.create_element("span");
        inner.style_mut(&mut document).set_property("color", "red");
        let second = document.create_text_node(" X X");
        inner.append_child(&mut document, second);
        outer.append_child(&mut document, inner);
        block.append_child(&mut document, outer);
        let suffix = document.create_text_node("Y");
        block.append_child(&mut document, suffix);
        document.body().append_child(&mut document, block);

        let root = document.to_component_tree();
        let flat = pre_flatten(&root);
        let layout = compute(&root, 200.0, 200.0).unwrap();
        let rects = flat
            .iter()
            .enumerate()
            .filter_map(|(index, node)| {
                let ComponentKind::Text { content } = &node.kind else {
                    return None;
                };
                let rect = layout.iter().find(|(_, candidate)| *candidate == index)?.0;
                Some((content.as_str(), rect))
            })
            .collect::<Vec<_>>();
        let first_line = rects.iter().find(|(text, _)| *text == "XXXX").unwrap().1;
        let suffix = rects.iter().find(|(text, _)| *text == "Y").unwrap().1;
        assert_eq!(suffix.y, first_line.y + 40.0, "{rects:?}");
        assert_eq!(suffix.x, first_line.x + 60.0, "{rects:?}");
        let block = layout.iter().find(|(_, index)| *index == 1).unwrap().0;
        assert_eq!(block.height, 60.0, "{rects:?}, block={block:?}");
    }

