        let third = document.create_text_node(" xxxxxxxxxxxxxxxxxxx");
        normal.append_child(&mut document, third);
        let pre = document.create_element("span");
        pre.style_mut(&mut document)
            .set_property("white-space", "pre");
        let fourth = document.create_text_node(" x    x  x xxxx xxxx ");
        pre.append_child(&mut document, fourth);
        normal.append_child(&mut document, pre);
        block.append_child(&mut document, normal);
