    #[test]
    fn breakable_inline_text_starts_in_the_leading_float_side_band() {
        let root = Component::row(
            Style {
                custom_properties: Some(HashMap::from([(
                    "--w3cos-internal-inline-formatting-context".into(),
                    "1".into(),
                )])),
                display: WDisp::Flex,
                width: WDim::Px(240.0),
                flex_wrap: WWrap::Wrap,
                ..Style::default()
            },
            vec![
                Component::boxed(
                    Style {
                        display: WDisp::Block,
                        float: WFloat::Left,
                        width: WDim::Px(60.0),
                        height: WDim::Px(6.0),
                        ..Style::default()
                    },
                    vec![],
                ),
                Component::text(
                    "alpha beta gamma delta epsilon zeta eta theta iota kappa lambda",
                    Style {
                        display: WDisp::Inline,
                        font_size: 16.0,
                        line_height: 1.25,
                        ..Style::default()
                    },
                ),
            ],
        );
        let layout = compute(&root, 800.0, 600.0).unwrap();
        let floating = layout.iter().find(|(_, index)| *index == 1).unwrap().0;
        let text = layout.iter().find(|(_, index)| *index == 2).unwrap().0;
        assert!(
            text.width <= 240.0,
            "text must not retain its unwrapped intrinsic width: {text:?}"
        );
        assert!(
            text.y < floating.y + floating.height,
            "a breakable text line must begin beside the float, not below it: float={floating:?}, text={text:?}"
        );
        assert!(
            layout[0].0.height >= 40.0,
            "wrapped lines contribute parent height"
        );
    }

