    #[test]
    fn clearing_line_break_constrains_later_floats_across_anonymous_groups() {
        for (clear, marked, expected_y) in [
            (WClear::Both, true, 20.0),
            (WClear::Left, true, 20.0),
            (WClear::Right, true, 0.0),
            (WClear::Both, false, 0.0),
        ] {
            let floating = || Component::boxed(Style { float: WFloat::Left,
                width: WDim::Px(40.0), height: WDim::Px(20.0), ..Style::default() }, vec![]);
            let group = || {
                let mut style = Style { display: WDisplay::Flex, ..Style::default() };
                style.custom_properties.get_or_insert_with(Default::default)
                    .insert("--w3cos-internal-anonymous-float-group".into(), "1".into());
                Component::row(style, vec![floating(), floating()])
            };
            let mut break_style = Style { display: WDisplay::Inline, clear, ..Style::default() };
            if marked {
                break_style.custom_properties.get_or_insert_with(Default::default)
                    .insert("--w3cos-internal-clearing-line-break".into(), "1".into());
            }
            let root = Component::boxed(Style { display: WDisplay::Block, ..Style::default() }, vec![
                group(), Component::text("\u{2028}", break_style), group()]);
            let rect = |x, y, width, height| LayoutRect { x, y, width, height };
            let mut layout = vec![
                (rect(0.0, 0.0, 200.0, 40.0), 0),
                (rect(0.0, 0.0, 200.0, 20.0), 1),
                (rect(0.0, 0.0, 40.0, 20.0), 2),
                (rect(40.0, 0.0, 40.0, 20.0), 3),
                (rect(80.0, 0.0, 0.0, 18.0), 4),
                (rect(0.0, 0.0, 200.0, 20.0), 5),
                (rect(80.0, 0.0, 40.0, 20.0), 6),
                (rect(120.0, 0.0, 40.0, 20.0), 7),
            ];
            project_shared_bfc_float_collisions(&mut layout, &pre_flatten(&root), 800.0, 600.0);
            assert_eq!(layout[6].0.y, expected_y, "clear={clear:?}, marked={marked}");
            assert_eq!(layout[7].0.y, expected_y);
            if expected_y > 0.0 {
                assert_eq!((layout[6].0.x, layout[7].0.x), (0.0, 40.0));
            }
        }
    }

    #[test]
    fn shared_bfc_float_collision_respects_opposing_and_same_side_overflow_rules() {
        for side in [WFloat::Left, WFloat::Right] {
            for (same, width, expected_y) in [
                (false, 425.0, 0.0),
                (false, 475.0, 300.0),
                (true, 425.0, 300.0),
            ] {
                let prior_side = if same {
                    side
                } else if side == WFloat::Left {
                    WFloat::Right
                } else {
                    WFloat::Left
                };
                let mut wrapper = Style {
                    display: WDisp::Block,
                    width: WDim::Px(400.0),
                    ..Style::default()
                };
                if (side == WFloat::Left) == same {
                    wrapper.margin.left = WSpacing::Px(100.0);
                } else {
                    wrapper.margin.right = WSpacing::Px(100.0);
                }
                let root = Component::row(
                    Style {
                        display: WDisp::Block,
                        float: WFloat::Left,
                        width: WDim::Px(500.0),
                        height: WDim::Px(500.0),
                        ..Style::default()
                    },
                    vec![
                        Component::row(
                            Style {
                                display: WDisp::Block,
                                float: prior_side,
                                width: WDim::Px(50.0),
                                height: WDim::Px(300.0),
                                ..Style::default()
                            },
                            vec![],
                        ),
                        Component::row(
                            wrapper,
                            vec![Component::row(
                                Style {
                                    display: WDisp::Block,
                                    float: side,
                                    width: WDim::Px(width),
                                    height: WDim::Px(10.0),
                                    ..Style::default()
                                },
                                vec![],
                            )],
                        ),
                    ],
                );
                let layout = compute(&root, 800.0, 600.0).unwrap();
                let get = |index| layout.iter().find(|(_, i)| *i == index).unwrap().0;
                assert_eq!(
                    get(3).y - get(0).y,
                    expected_y,
                    "side={side:?} same={same} width={width}"
                );
            }
        }
    }

