    #[test]
    fn right_float_shares_anonymous_group_last_row_but_not_a_real_flex_box() {
        for (anonymous, relative, clear) in [
            (false, 0.0, WClear::None),
            (true, 0.0, WClear::None),
            (false, 5.0, WClear::None),
            (true, 5.0, WClear::None),
            (true, 0.0, WClear::Both),
            (true, 5.0, WClear::Both),
        ] {
            let mut group_style = Style {
                display: WDisp::Flex,
                flex_wrap: WWrap::Wrap,
                width: WDim::Percent(100.0),
                ..Style::default()
            };
            if anonymous {
                group_style
                    .custom_properties
                    .get_or_insert_with(Default::default)
                    .insert("--w3cos-internal-anonymous-float-group".into(), "1".into());
            }
            let floating = |width, height, side| {
                Component::row(
                    Style {
                        display: WDisp::Block,
                        float: side,
                        width: WDim::Px(width),
                        height: WDim::Px(height),
                        ..Style::default()
                    },
                    Vec::new(),
                )
            };
            let mut right = floating(30.0, 30.0, WFloat::Right);
            right.style.position = WPos::Relative;
            right.style.top = WDim::Px(relative);
            right.style.clear = clear;
            let root = Component::row(
                Style {
                    display: WDisp::Block,
                    width: WDim::Px(100.0),
                    ..Style::default()
                },
                vec![
                    Component::row(
                        group_style,
                        vec![
                            floating(100.0, 100.0, WFloat::Left),
                            floating(30.0, 30.0, WFloat::Left),
                        ],
                    ),
                    right,
                ],
            );
            let layout = compute(&root, 800.0, 600.0).unwrap();
            let get = |index| layout.iter().find(|(_, i)| *i == index).unwrap().0;
            let expected_y = if anonymous && clear == WClear::None {
                get(3).y
            } else {
                get(1).y + get(1).height
            } + relative;
            assert_eq!(get(4).y, expected_y, "anonymous={anonymous}");
            assert_eq!(get(4).x, 70.0);
        }
    }

